insert into chapters (id, course_id, level_id, position, title, title_fr, story, boss) values
  ('b1-c1', 'course-B1', 'B1', 0, 'Everyday Life & Experience', 'Vie quotidienne et expériences', 'Vous arrivez à Port Lexis, une ville portuaire où tout le monde parle anglais. Première mission : vous installer et raconter votre parcours.', '{"name":"The Time Keeper","title":"Gardien des temps","lore":"Il confond le passé et le présent de quiconque hésite. Prouvez que vous maîtrisez les temps.","avatar":"clock"}'::jsonb),
  ('b1-c2', 'course-B1', 'B1', 1, 'Plans & Possibilities', 'Projets et possibilités', 'Le port prépare un grand festival. On vous confie l''organisation : planifier, prévoir, anticiper.', '{"name":"The Oracle of If","title":"L''Oracle du Si","lore":"Elle ne répond qu''à ceux qui savent exprimer une condition.","avatar":"orb"}'::jsonb),
  ('b1p-c1', 'course-B1+', 'B1+', 0, 'Reports & Rumours', 'Rapports et rumeurs', 'Le journal de Port Lexis vous recrute comme reporter stagiaire. Il faut décrire, rapporter, citer.', '{"name":"The Echo","title":"L''Écho","lore":"Elle répète tout de travers. Rapportez fidèlement les paroles pour la faire taire.","avatar":"wave"}'::jsonb),
  ('b1p-c2', 'course-B1+', 'B1+', 1, 'Describing the World', 'Décrire le monde', 'Vous rejoignez une entreprise de la ville. Courriers, notes internes, réclamations : il faut être précis.', '{"name":"The Bureaucrat","title":"Le Bureaucrate","lore":"Il rejette tout document mal construit. Vos phrases devront être impeccables.","avatar":"stamp"}'::jsonb),
  ('b2-c1', 'course-B2', 'B2', 0, 'What If?', 'Et si… ?', 'Une tempête menace l''archipel. Le conseil de la ville vous demande d''imaginer les scénarios possibles.', '{"name":"The Regret Wraith","title":"Le Spectre du Regret","lore":"Il se nourrit des « si seulement ». Maîtrisez l''irréel pour le dissiper.","avatar":"ghost"}'::jsonb),
  ('b2-c2', 'course-B2', 'B2', 1, 'Deduction & Persuasion', 'Déduction et persuasion', 'Un mystère agite la Bourse de Port Lexis. Enquêtez, déduisez, convainquez.', '{"name":"The Detective","title":"Le Détective","lore":"Il ne croit que ceux qui déduisent avec rigueur.","avatar":"magnifier"}'::jsonb),
  ('b2p-c1', 'course-B2+', 'B2+', 0, 'The Art of Emphasis', 'L''art de l''emphase', 'Le théâtre de la ville vous demande d''écrire et de prononcer des discours marquants.', '{"name":"The Herald","title":"Le Héraut","lore":"Seuls les orateurs capables de mettre leurs idées en relief peuvent passer.","avatar":"trumpet"}'::jsonb),
  ('b2p-c2', 'course-B2+', 'B2+', 1, 'Building an Argument', 'Construire une argumentation', 'Vous représentez Port Lexis au grand concours d''éloquence de l''archipel.', '{"name":"The Sophist","title":"Le Sophiste","lore":"Il retourne chaque argument mal articulé contre vous.","avatar":"mask"}'::jsonb),
  ('c1-c1', 'course-C1', 'C1', 0, 'Formal Precision', 'Précision formelle', 'L''Université du Sommet vous invite comme chercheur associé. Le niveau d''exigence est maximal.', '{"name":"The Archivist","title":"L''Archiviste","lore":"Gardienne des textes savants, elle teste chaque nuance de registre.","avatar":"scroll"}'::jsonb),
  ('c1-c2', 'course-C1', 'C1', 1, 'The Summit: Nuance', 'Le Sommet : la nuance', 'Dernière ascension. Au sommet, seule la maîtrise des nuances permet de passer.', '{"name":"The Summit Sphinx","title":"Le Sphinx du Sommet","lore":"L''ultime gardien. Il pose ses énigmes dans un anglais d''une grande finesse.","avatar":"sphinx"}'::jsonb)
insert into grammar_topics (id, level_id, title, title_fr, summary_fr, content) values
  ('tenses-review', 'B1', 'The English tense system', 'Panorama des temps anglais', 'Comprendre la logique aspect simple / continu / parfait pour choisir le bon temps.', '{"explanationFr":["En anglais, un temps combine une **époque** (passé, présent, futur) et un **aspect**. L''aspect **simple** présente un fait global ou habituel ; l''aspect **continu** (be + -ing) présente une action en cours, temporaire ou inachevée ; l''aspect **parfait** (have + participe passé) relie deux moments : une action antérieure et son lien avec un point de référence.","Le **present simple** exprime les habitudes, les vérités générales et les états (I *work* in Lyon). Le **present continuous** exprime ce qui se passe maintenant ou temporairement (I*''m working* from home this week).","Le **past simple** décrit une action terminée à un moment précis du passé (I *moved* in 2019). Le **past continuous** décrit l''arrière-plan, une action en cours dans le passé (I *was cooking* when you called).","Les **verbes d''état** (know, believe, want, belong, seem…) ne se mettent normalement pas à la forme continue : on dit *I know*, jamais *I''m knowing*."],"explanationEn":["English tenses combine time (past, present, future) with aspect. Simple aspect presents an action as a complete fact or habit. Continuous aspect (be + -ing) shows an action in progress, temporary or unfinished. Perfect aspect (have + past participle) connects an earlier action with a later point of reference.","Choosing the right tense is less about translating from French and more about asking: is this a habit, a temporary situation, a finished event, or something connected to now?"],"forms":[{"label":"Present simple","pattern":"subject + base verb (+s)","example":"She works in finance."},{"label":"Present continuous","pattern":"am/is/are + verb-ing","example":"She''s working on a new report."},{"label":"Past simple","pattern":"verb-ed / irregular past","example":"We met in 2018."},{"label":"Past continuous","pattern":"was/were + verb-ing","example":"It was raining when we left."}],"examples":[{"en":"Water boils at 100 °C.","fr":"L''eau bout à 100 °C.","note":"vérité générale → present simple"},{"en":"I''m staying with my cousin until I find a flat.","fr":"Je loge chez mon cousin jusqu''à ce que je trouve un appartement.","note":"situation temporaire"},{"en":"While I was waiting for the bus, I read the news.","fr":"Pendant que j''attendais le bus, j''ai lu les infos.","note":"arrière-plan + action ponctuelle"},{"en":"This bag belongs to Tom.","fr":"Ce sac appartient à Tom.","note":"verbe d''état : pas de -ing"}],"mistakes":[{"wrong":"I am knowing the answer.","right":"I know the answer.","why":"know est un verbe d''état : il ne se met pas à la forme continue."},{"wrong":"Every morning I am taking the train.","right":"Every morning I take the train.","why":"Une habitude s''exprime au present simple."},{"wrong":"When I arrived, they had dinner.","right":"When I arrived, they were having dinner.","why":"Pour une action en cours au moment d''un événement passé, on utilise le past continuous."}]}'::jsonb),
  ('present-perfect', 'B1', 'Present perfect vs past simple', 'Present perfect ou past simple ?', 'Relier le passé au présent : expérience, résultat, durée jusqu''à maintenant.', '{"explanationFr":["Le **present perfect** (have/has + participe passé) relie une action passée au **moment présent**. On ne s''intéresse pas au *moment* de l''action, mais à son lien avec maintenant : une expérience (*I''ve been to Japan*), un résultat visible (*I''ve lost my keys*, je ne les ai toujours pas), une durée qui continue (*I''ve lived here for five years*, j''y vis encore).","Le **past simple** situe une action dans un **passé terminé**, coupé du présent, souvent avec un repère précis : *yesterday, last year, in 2019, two days ago, when I was a child*. Dès qu''il y a un repère de temps passé et terminé, le present perfect est impossible.","**for** + durée (for three years) ; **since** + point de départ (since 2020, since Monday). Attention, le français dit « j''habite ici depuis 5 ans » au présent, mais l''anglais exige *I have lived / I have been living here for 5 years*.","Le **present perfect continuous** (have been + -ing) insiste sur la durée ou l''activité elle-même : *I''ve been working all day* (je suis fatigué), alors que *I''ve written three emails* insiste sur le résultat chiffré."],"explanationEn":["Use the present perfect when the time of the action is not important or not finished, and the action is connected to now: life experience, recent events with present results, and situations that started in the past and continue.","Use the past simple for finished actions at a definite time in the past. Time expressions such as yesterday, last week, in 2015 or ago require the past simple."],"forms":[{"label":"Affirmative","pattern":"have/has + past participle","example":"She has finished the project."},{"label":"Question","pattern":"Have/Has + subject + past participle?","example":"Have you ever worked abroad?"},{"label":"Continuous","pattern":"have/has been + verb-ing","example":"They''ve been waiting for an hour."},{"label":"Past simple contrast","pattern":"verb-ed + finished time","example":"She finished it last Friday."}],"examples":[{"en":"I''ve never tried sushi.","fr":"Je n''ai jamais goûté de sushis.","note":"expérience de vie"},{"en":"She has just left the office.","fr":"Elle vient de quitter le bureau.","note":"just = venir de"},{"en":"We''ve known each other since university.","fr":"Nous nous connaissons depuis la fac.","note":"état qui continue"},{"en":"I saw that film last week.","fr":"J''ai vu ce film la semaine dernière.","note":"repère passé terminé → past simple"},{"en":"Have you finished yet? — Not yet.","fr":"Tu as fini ? — Pas encore.","note":"yet en question/négation"}],"mistakes":[{"wrong":"I live here since 2018.","right":"I''ve lived here since 2018.","why":"Avec since/for et une situation qui dure jusqu''à maintenant, le français utilise le présent, l''anglais le present perfect."},{"wrong":"I have seen him yesterday.","right":"I saw him yesterday.","why":"yesterday est un moment passé terminé : present perfect impossible."},{"wrong":"How long are you working here?","right":"How long have you been working here?","why":"How long + durée jusqu''à maintenant → present perfect (continuous)."}]}'::jsonb),
  ('past-perfect', 'B1', 'Past perfect & narrative tenses', 'Past perfect et temps du récit', 'Raconter une histoire en hiérarchisant les événements : avant, pendant, après.', '{"explanationFr":["Le **past perfect** (had + participe passé) exprime une action **antérieure** à un autre moment du passé. C''est l''équivalent du plus-que-parfait français : *When I arrived, the train had left* (il était déjà parti avant mon arrivée).","Dans un récit, on combine trois temps : le **past simple** pour la suite des événements principaux, le **past continuous** pour le décor et les actions en cours, le **past perfect** pour revenir en arrière.","On ne met pas le past perfect partout : si l''ordre est évident (avec *after*, *before*, ou une simple chronologie), le past simple suffit. Le past perfect est indispensable quand l''ordre des événements serait sinon ambigu.","Le **past perfect continuous** (had been + -ing) insiste sur la durée d''une activité avant un moment passé : *She was tired because she had been running.*"],"explanationEn":["Use the past perfect to show that one past action happened before another past action or time. It helps the listener ''go back'' in a story.","Narratives typically use the past simple for main events, the past continuous for background, and the past perfect for earlier events."],"forms":[{"label":"Past perfect","pattern":"had + past participle","example":"They had already eaten."},{"label":"Past perfect continuous","pattern":"had been + verb-ing","example":"He had been working there for years."},{"label":"Typical markers","pattern":"already, just, never…before, by the time","example":"By the time we arrived, the show had started."}],"examples":[{"en":"I didn''t recognise her because she had changed so much.","fr":"Je ne l''ai pas reconnue car elle avait tellement changé."},{"en":"By the time the police arrived, the thieves had escaped.","fr":"Quand la police est arrivée, les voleurs s''étaient enfuis."},{"en":"It was the first time I had ever seen snow.","fr":"C''était la première fois que je voyais de la neige.","note":"first time + passé → past perfect"},{"en":"We had been driving for hours when the car broke down.","fr":"Nous roulions depuis des heures quand la voiture est tombée en panne."}],"mistakes":[{"wrong":"When I got to the station, the train already left.","right":"When I got to the station, the train had already left.","why":"Le départ du train est antérieur à mon arrivée : past perfect."},{"wrong":"I had gone to the cinema yesterday.","right":"I went to the cinema yesterday.","why":"Sans autre repère passé, le past perfect n''a pas de raison d''être."},{"wrong":"She was tired because she has worked all day.","right":"She was tired because she had been working all day.","why":"Dans un récit au passé, le present perfect devient past perfect."}]}'::jsonb),
  ('future-forms', 'B1', 'Talking about the future', 'Exprimer le futur : will, going to, present continuous', 'Choisir la forme du futur selon l''intention, la décision ou l''organisation.', '{"explanationFr":["L''anglais n''a pas un seul futur : la forme dépend de ce que vous voulez dire. **will** exprime une décision prise sur le moment (*I''ll get it!*), une promesse, une offre, ou une prédiction fondée sur une opinion (*I think it will rain*).","**be going to** exprime une **intention déjà décidée** (*I''m going to look for a new job*) ou une prédiction fondée sur un indice présent (*Look at those clouds — it''s going to rain*).","Le **present continuous** exprime un **arrangement organisé** avec d''autres personnes, souvent avec une date (*I''m meeting the client on Tuesday*). Le **present simple** sert aux horaires officiels (*The train leaves at 6.15*).","Après **when, as soon as, before, after, until** à valeur future, on utilise le présent : *I''ll call you when I arrive* (et non *when I will arrive*)."],"explanationEn":["Use will for spontaneous decisions, offers, promises and opinions about the future; be going to for plans and evidence-based predictions; the present continuous for fixed arrangements; and the present simple for timetables.","In time clauses introduced by when, as soon as, until, before and after, use a present tense to refer to the future."],"forms":[{"label":"will","pattern":"will + base verb","example":"I''ll send you the file tonight."},{"label":"be going to","pattern":"am/is/are going to + base verb","example":"We''re going to redesign the website."},{"label":"Arrangement","pattern":"present continuous + time","example":"She''s flying to Madrid on Friday."},{"label":"Timetable","pattern":"present simple","example":"The conference starts at 9."}],"examples":[{"en":"The phone''s ringing. — Don''t worry, I''ll answer it.","fr":"Le téléphone sonne. — T''inquiète, je réponds.","note":"décision spontanée"},{"en":"I''m going to take a year off to travel.","fr":"Je vais prendre une année sabbatique pour voyager.","note":"intention"},{"en":"We''re having dinner with the Martins on Saturday.","fr":"On dîne chez les Martin samedi.","note":"arrangement"},{"en":"Let me know as soon as you hear from them.","fr":"Préviens-moi dès que tu as de leurs nouvelles.","note":"présent après as soon as"}],"mistakes":[{"wrong":"I will call you when I will arrive.","right":"I''ll call you when I arrive.","why":"Après when (sens futur), on utilise le présent."},{"wrong":"I meet my dentist tomorrow at 10.","right":"I''m seeing my dentist tomorrow at 10.","why":"Un rendez-vous organisé s''exprime au present continuous."},{"wrong":"Look at that car! It will crash!","right":"Look at that car! It''s going to crash!","why":"Prédiction fondée sur un indice visible → going to."}]}'::jsonb),
  ('conditionals-01', 'B1', 'Zero & first conditionals', 'Conditionnels 0 et 1 (réel)', 'Exprimer des vérités générales et des conséquences probables.', '{"explanationFr":["Le **conditionnel zéro** (*If + présent, présent*) exprime une vérité générale ou un fait toujours vrai : *If you heat ice, it melts.* *If* peut souvent être remplacé par *when*.","Le **premier conditionnel** (*If + présent, will + base verbale*) exprime une condition **réelle et probable** dans le futur : *If it rains tomorrow, we''ll cancel the picnic.* Comme en français (« s''il pleut, nous annulerons »), on ne met **jamais will après if** dans ce sens.","**unless** = *if not* (à moins que) : *We''ll be late unless we leave now.* On peut aussi utiliser *as long as / provided that* (à condition que), *in case* (au cas où, par précaution).","La subordonnée peut venir en premier (avec une virgule) ou en second (sans virgule)."],"explanationEn":["Zero conditional: if + present, present — for facts and things that are always true. First conditional: if + present, will + verb — for real, likely situations in the future.","Unless means ''if not''. In case means ''as a precaution against something that might happen''."],"forms":[{"label":"Zero","pattern":"If + present simple, present simple","example":"If you press this button, the machine stops."},{"label":"First","pattern":"If + present simple, will + verb","example":"If you finish early, you''ll get a bonus."},{"label":"Unless","pattern":"unless + present (= if … not)","example":"I won''t go unless you come with me."},{"label":"In case","pattern":"in case + present","example":"Take an umbrella in case it rains."}],"examples":[{"en":"If customers are unhappy, they leave bad reviews.","fr":"Si les clients sont mécontents, ils laissent de mauvais avis.","note":"vérité générale"},{"en":"If you send me the slides, I''ll check them tonight.","fr":"Si tu m''envoies les slides, je les vérifierai ce soir."},{"en":"You won''t improve unless you practise every day.","fr":"Tu ne progresseras pas à moins de t''entraîner tous les jours."},{"en":"I''ll take my laptop in case I need to work on the train.","fr":"Je prends mon ordi au cas où je devrais travailler dans le train."}],"mistakes":[{"wrong":"If it will rain, we will stay home.","right":"If it rains, we''ll stay home.","why":"Pas de will après if dans le premier conditionnel."},{"wrong":"Unless you don''t hurry, you''ll miss the bus.","right":"Unless you hurry, you''ll miss the bus.","why":"unless est déjà négatif : pas de double négation."},{"wrong":"Take a coat if it gets cold.","right":"Take a coat in case it gets cold.","why":"Pour une précaution, on utilise in case."}]}'::jsonb),
  ('passive', 'B1+', 'The passive voice', 'La voix passive', 'Mettre l''accent sur l''action ou son résultat plutôt que sur son auteur.', '{"explanationFr":["Le passif se forme avec **be** conjugué au temps voulu + **participe passé**. C''est le verbe *be* qui porte le temps : *is made, was made, has been made, will be made, is being made*.","On l''utilise quand l''auteur de l''action est **inconnu, évident ou sans importance**, ou quand on veut mettre en valeur le résultat : *The bridge was built in 1890.* C''est très fréquent dans les textes techniques, scientifiques, journalistiques et professionnels.","L''agent s''introduit avec **by** seulement s''il apporte une information utile : *The novel was written by a 19-year-old student.*","Particularités : **get** + participe passé au passif informel (*He got promoted*) ; le passif des verbes à deux compléments (*I was given a laptop*) ; les tournures impersonnelles **It is said that… / He is thought to be…** (on dit que…, on pense que…). Le français utilise souvent « on » là où l''anglais utilise le passif."],"explanationEn":["Form the passive with be in the appropriate tense plus the past participle. Use it when the agent is unknown, obvious or unimportant, or when the focus is the process or result.","Reporting structures such as It is believed that… or She is said to be… are common in formal writing and news reports."],"forms":[{"label":"Present","pattern":"am/is/are + p.p.","example":"Thousands of emails are sent every second."},{"label":"Past","pattern":"was/were + p.p.","example":"The meeting was postponed."},{"label":"Present perfect","pattern":"has/have been + p.p.","example":"Your order has been shipped."},{"label":"Modal","pattern":"modal + be + p.p.","example":"The form must be signed."},{"label":"Continuous","pattern":"is/was being + p.p.","example":"The road is being repaired."}],"examples":[{"en":"English is spoken in many countries.","fr":"On parle anglais dans de nombreux pays."},{"en":"The suspect has been arrested.","fr":"Le suspect a été arrêté."},{"en":"I was offered a job in Dublin.","fr":"On m''a proposé un poste à Dublin.","note":"passif avec la personne en sujet"},{"en":"The company is said to be in financial difficulty.","fr":"On dit que l''entreprise est en difficulté financière."}],"mistakes":[{"wrong":"The house was build in 1920.","right":"The house was built in 1920.","why":"Il faut le participe passé (built), pas la base verbale."},{"wrong":"It was happened yesterday.","right":"It happened yesterday.","why":"happen est intransitif (pas de complément d''objet) : il n''a pas de passif."},{"wrong":"The results will publish next week.","right":"The results will be published next week.","why":"Avec un modal, le passif est modal + be + participe passé."}]}'::jsonb),
  ('reported-speech', 'B1+', 'Reported speech', 'Le discours indirect', 'Rapporter des paroles, des questions et des ordres avec précision.', '{"explanationFr":["Quand le verbe introducteur est au passé (*said, told, asked*), on **recule généralement les temps** d''un cran : présent → passé, present perfect / past simple → past perfect, will → would, can → could, must → had to.","Les repères changent aussi : *today → that day, tomorrow → the next day / the following day, yesterday → the day before, here → there, this → that, ago → before*.","**say** s''emploie sans complément de personne (*She said that…*), **tell** exige un complément (*She told me that…*). Pour les questions : *He asked me where I lived* — **ordre affirmatif, pas d''auxiliaire do** ; pour les questions fermées : *He asked if / whether I was ready*.","Ordres et demandes : *tell / ask someone (not) to do something*. Les verbes de rapport enrichissent le style : *suggest, recommend, admit, deny, warn, insist, promise, refuse, remind*. Si l''information est toujours vraie, le recul des temps est facultatif : *She said she lives in Lyon.*"],"explanationEn":["In reported speech after a past reporting verb, tenses usually move one step back and time/place references change.","Reported questions use statement word order without do/does/did. Use a range of reporting verbs (admit, suggest, warn, deny) to report the speaker''s intention precisely."],"forms":[{"label":"Statement","pattern":"say (that) / tell sb (that) + backshift","example":"He said (that) he was tired."},{"label":"Wh- question","pattern":"ask + wh- + subject + verb","example":"She asked where the station was."},{"label":"Yes/no question","pattern":"ask + if/whether + subject + verb","example":"They asked if I could help."},{"label":"Command","pattern":"tell/ask sb (not) to + verb","example":"He told us not to worry."},{"label":"Reporting verbs","pattern":"suggest + -ing / admit + -ing / warn sb not to…","example":"She suggested taking a break."}],"examples":[{"en":"\"I''m leaving tomorrow.\" → She said she was leaving the next day.","fr":"Elle a dit qu''elle partait le lendemain."},{"en":"\"Have you seen my phone?\" → He asked me if I had seen his phone.","fr":"Il m''a demandé si j''avais vu son téléphone."},{"en":"\"Don''t touch the screen.\" → The technician told us not to touch the screen.","fr":"Le technicien nous a dit de ne pas toucher l''écran."},{"en":"\"I didn''t take the money.\" → He denied taking the money.","fr":"Il a nié avoir pris l''argent."}],"mistakes":[{"wrong":"She said me that she was busy.","right":"She told me (that) she was busy.","why":"say n''a pas de complément de personne direct ; tell en exige un."},{"wrong":"He asked me where did I live.","right":"He asked me where I lived.","why":"Dans une question indirecte, ordre sujet-verbe et pas d''auxiliaire do."},{"wrong":"She suggested me to go.","right":"She suggested that I (should) go. / She suggested going.","why":"suggest ne se construit pas avec complément + to."}]}'::jsonb),
  ('relative-clauses', 'B1+', 'Relative clauses', 'Les propositions relatives', 'Définir ou compléter une information avec who, which, that, whose, where.', '{"explanationFr":["**who** pour les personnes, **which** pour les choses, **that** pour les deux (seulement dans les relatives *déterminatives*), **whose** pour la possession (dont le / la), **where** pour un lieu, **when** pour un moment.","Une relative **déterminative** (*defining*) est indispensable pour identifier de qui ou de quoi on parle : *The colleague who helped me is on holiday.* Pas de virgules.","Une relative **explicative** (*non-defining*) ajoute une information supplémentaire, entre **virgules** ; *that* y est interdit : *My manager, who is French, speaks four languages.* *which* peut aussi reprendre toute une proposition : *He missed the train, which annoyed him.*","Dans une déterminative, on peut **omettre le pronom quand il est complément** : *The book (that) I''m reading is brilliant.* Mais pas quand il est sujet : *The man who lives next door…* En style soutenu, la préposition se place avant *whom/which* : *the person to whom I spoke* ; en style courant, à la fin : *the person I spoke to*."],"explanationEn":["Defining relative clauses identify the noun and take no commas; that is possible and the pronoun can be omitted when it is the object. Non-defining clauses add extra information, use commas and never take that.","Whose shows possession; where and when refer to places and times. Which can refer back to a whole clause."],"forms":[{"label":"Defining (subject)","pattern":"noun + who/which/that + verb","example":"People who exercise sleep better."},{"label":"Defining (object)","pattern":"noun + (that/which/who) + subject + verb","example":"The app (that) I use is free."},{"label":"Non-defining","pattern":"noun, who/which + clause,","example":"Lyon, which is my hometown, is famous for food."},{"label":"Possession","pattern":"noun + whose + noun","example":"The student whose essay won is from Lille."}],"examples":[{"en":"That''s the restaurant where we had our first date.","fr":"C''est le restaurant où nous avons eu notre premier rendez-vous."},{"en":"I have a friend whose father is an astronaut.","fr":"J''ai un ami dont le père est astronaute."},{"en":"She passed all her exams, which surprised everyone.","fr":"Elle a réussi tous ses examens, ce qui a surpris tout le monde."},{"en":"The person I spoke to was very helpful.","fr":"La personne à qui j''ai parlé a été très serviable.","note":"pronom omis, préposition finale"}],"mistakes":[{"wrong":"My sister, that lives in Paris, is a doctor.","right":"My sister, who lives in Paris, is a doctor.","why":"that est interdit dans une relative explicative (entre virgules)."},{"wrong":"The man which called you is here.","right":"The man who called you is here.","why":"Pour une personne : who (ou that)."},{"wrong":"He failed the test, what disappointed him.","right":"He failed the test, which disappointed him.","why":"Pour reprendre toute une proposition : which (« ce qui »)."}]}'::jsonb),
  ('gerunds-infinitives', 'B1+', 'Gerunds and infinitives', 'Gérondif (-ing) ou infinitif (to) ?', 'Savoir quelle forme suit un verbe, une préposition ou un adjectif.', '{"explanationFr":["Certains verbes sont suivis de **-ing** : *enjoy, avoid, mind, finish, suggest, consider, keep, practise, deny, risk, can''t stand*. D''autres de **to + base verbale** : *want, decide, hope, plan, agree, refuse, manage, afford, promise, expect*.","Après une **préposition**, on utilise toujours **-ing** : *interested in learning, good at solving, before leaving, instead of complaining*. Attention : dans *look forward to*, *be used to*, *object to*, **to est une préposition** → *I look forward to hearing from you.*","Certains verbes changent de **sens** : *remember / forget + -ing* (souvenir d''une action passée) vs *+ to* (se souvenir de faire quelque chose) ; *stop smoking* (arrêter de fumer) vs *stop to smoke* (s''arrêter pour fumer) ; *try opening the window* (essayer, comme expérience) vs *try to open* (faire un effort).","Le gérondif peut être **sujet** de la phrase : *Learning a language takes time.* L''infinitif exprime le **but** : *I came here to learn.*"],"explanationEn":["Some verbs take -ing, others take to-infinitive, and some take both with a change in meaning (remember, forget, stop, try, regret).","After prepositions, always use the -ing form. Remember that ''to'' is a preposition in look forward to, be used to, get used to and object to."],"forms":[{"label":"Verb + -ing","pattern":"enjoy / avoid / suggest + -ing","example":"I avoid driving at night."},{"label":"Verb + to","pattern":"decide / manage / refuse + to + verb","example":"She managed to fix it."},{"label":"Preposition + -ing","pattern":"preposition + -ing","example":"Thanks for helping me."},{"label":"Meaning change","pattern":"stop/remember/try + -ing vs to","example":"Remember to lock the door."}],"examples":[{"en":"I''m looking forward to meeting you.","fr":"J''ai hâte de vous rencontrer."},{"en":"We can''t afford to lose this client.","fr":"Nous ne pouvons pas nous permettre de perdre ce client."},{"en":"I remember visiting this museum as a child.","fr":"Je me souviens d''avoir visité ce musée enfant."},{"en":"He stopped to answer the phone.","fr":"Il s''est arrêté pour répondre au téléphone."}],"mistakes":[{"wrong":"I look forward to hear from you.","right":"I look forward to hearing from you.","why":"Dans look forward to, to est une préposition → -ing."},{"wrong":"She suggested to go to the beach.","right":"She suggested going to the beach.","why":"suggest est suivi de -ing (ou de that…)."},{"wrong":"I''m used to work late.","right":"I''m used to working late.","why":"be used to (être habitué à) + -ing."}]}'::jsonb),
  ('conditionals-23', 'B2', 'Second, third & mixed conditionals', 'Conditionnels 2, 3 et mixtes (irréel)', 'Imaginer, regretter, refaire le passé : l''hypothèse irréelle.', '{"explanationFr":["Le **deuxième conditionnel** (*If + past simple, would + base verbale*) exprime une situation **irréelle ou peu probable au présent / futur** : *If I had more time, I would learn Japanese* (mais je n''ai pas le temps). Avec *be*, la forme soutenue est *If I were* (*If I were you, I''d accept*).","Le **troisième conditionnel** (*If + past perfect, would have + participe passé*) exprime une hypothèse sur le **passé**, qui ne peut plus changer : *If we had left earlier, we wouldn''t have missed the flight.* Il sert souvent à exprimer un regret ou une critique.","Le **conditionnel mixte** croise les époques. Passé → présent : *If I had studied medicine, I would be a doctor now.* Présent → passé : *If I weren''t so shy, I would have spoken to her yesterday.*","Formes associées : **I wish / If only** + past simple (regret présent), + past perfect (regret passé), + would (agacement) ; **could / might** à la place de *would* pour la possibilité. En style soutenu, l''inversion remplace *if* : *Had I known, I would have called* (voir le cours *Inversion*)."],"explanationEn":["Second conditional: if + past simple, would + infinitive — hypothetical present or future. Third conditional: if + past perfect, would have + past participle — hypothetical past.","Mixed conditionals combine a past condition with a present result, or a present condition with a past result. Wish and if only express regret with the same backshift."],"forms":[{"label":"Second","pattern":"If + past simple, would + verb","example":"If I won the lottery, I''d travel the world."},{"label":"Third","pattern":"If + had + p.p., would have + p.p.","example":"If she had applied, she would have got the job."},{"label":"Mixed (past → now)","pattern":"If + had + p.p., would + verb","example":"If I had taken that job, I''d live in London now."},{"label":"Wish (past regret)","pattern":"I wish + had + p.p.","example":"I wish I had listened to you."}],"examples":[{"en":"If I were in your position, I''d ask for a pay rise.","fr":"À ta place, je demanderais une augmentation."},{"en":"We would have won if the referee hadn''t made that mistake.","fr":"Nous aurions gagné si l''arbitre n''avait pas fait cette erreur."},{"en":"If he had saved more money, he wouldn''t be in debt now.","fr":"S''il avait épargné davantage, il ne serait pas endetté aujourd''hui.","note":"mixte"},{"en":"I wish I could speak Spanish.","fr":"J''aimerais savoir parler espagnol."}],"mistakes":[{"wrong":"If I would have known, I would have come.","right":"If I had known, I would have come.","why":"Jamais would dans la subordonnée en if : on utilise le past perfect."},{"wrong":"If I would be rich, I would buy a boat.","right":"If I were rich, I would buy a boat.","why":"Le deuxième conditionnel utilise le past simple après if (were pour be)."},{"wrong":"I wish I have more free time.","right":"I wish I had more free time.","why":"wish + past simple pour un regret au présent."}]}'::jsonb),
  ('future-perfect', 'B2', 'Future perfect & future continuous', 'Future perfect et future continuous', 'Se projeter : ce qui sera en cours ou accompli à un moment futur.', '{"explanationFr":["Le **future continuous** (*will be + -ing*) décrit une action **en cours à un moment précis du futur** : *This time tomorrow, I''ll be flying to Montreal.* Il sert aussi à demander poliment des projets : *Will you be using the car tonight?*","Le **future perfect** (*will have + participe passé*) décrit une action **accomplie avant** un moment futur : *By 2030, we will have reduced our emissions by 40%.* Le marqueur typique est **by** (d''ici, au plus tard) : *by Friday, by the time you arrive, by then*.","Le **future perfect continuous** (*will have been + -ing*) insiste sur la **durée** jusqu''à un moment futur : *In June, I''ll have been working here for ten years.*","Après *by the time / when* (sens futur), on garde le présent : *By the time you get here, we''ll have finished.*"],"explanationEn":["Use the future continuous for actions in progress at a future time; the future perfect for actions completed before a future time (often with by); the future perfect continuous for duration up to a future point."],"forms":[{"label":"Future continuous","pattern":"will be + verb-ing","example":"At 10, I''ll be presenting our results."},{"label":"Future perfect","pattern":"will have + p.p.","example":"By noon, they''ll have signed the deal."},{"label":"Future perfect continuous","pattern":"will have been + verb-ing","example":"By May, she''ll have been training for a year."}],"examples":[{"en":"Don''t call at 8 — we''ll be having dinner.","fr":"N''appelle pas à 20h, on sera en train de dîner."},{"en":"By the end of the course, you''ll have learnt 2,000 words.","fr":"À la fin du cours, vous aurez appris 2 000 mots."},{"en":"Next month I''ll have been living abroad for five years.","fr":"Le mois prochain, cela fera cinq ans que je vis à l''étranger."}],"mistakes":[{"wrong":"By next year I will finish my degree.","right":"By next year I will have finished my degree.","why":"by + moment futur → action accomplie avant : future perfect."},{"wrong":"By the time you will arrive, we''ll have left.","right":"By the time you arrive, we''ll have left.","why":"Présent après by the time à valeur future."},{"wrong":"At 9 tomorrow I''ll work.","right":"At 9 tomorrow I''ll be working.","why":"Action en cours à un moment précis du futur → future continuous."}]}'::jsonb),
  ('modals-advanced', 'B2', 'Advanced modal verbs', 'Modaux avancés : déduction, passé, obligation', 'Exprimer certitude, probabilité, reproche et nécessité avec nuance.', '{"explanationFr":["**Déduction au présent** : *must* (certitude positive : il doit être…), *can''t* (certitude négative : ce n''est pas possible), *might / may / could* (possibilité). *She must be at home — her car is outside.* *He can''t be serious!*","**Déduction au passé** : modal + **have + participe passé**. *They must have missed the train* (ils ont dû rater le train), *She can''t have forgotten* (elle n''a pas pu oublier), *He might have got lost* (il s''est peut-être perdu).","**Reproche / regret** : *should have + p.p.* (aurait dû), *shouldn''t have* (n''aurait pas dû), *could have* (aurait pu — possibilité non réalisée). *You should have told me!*","**Nécessité** : *must* (obligation venant du locuteur) vs *have to* (obligation extérieure) ; *mustn''t* = interdiction, mais *don''t have to* = absence d''obligation. *needn''t have + p.p.* = on l''a fait, mais c''était inutile ; *didn''t need to* = ce n''était pas nécessaire (souvent pas fait)."],"explanationEn":["Use must, can''t, might, may and could for deductions about the present; add have + past participle for deductions about the past.","Should have / could have express criticism, regret and unrealised possibilities. Distinguish mustn''t (prohibition) from don''t have to (no obligation), and needn''t have done (done, but unnecessary)."],"forms":[{"label":"Present deduction","pattern":"must / can''t / might + verb","example":"You must be exhausted."},{"label":"Past deduction","pattern":"must / can''t / might + have + p.p.","example":"She must have left early."},{"label":"Criticism","pattern":"should(n''t) have + p.p.","example":"We should have checked the forecast."},{"label":"Unnecessary past action","pattern":"needn''t have + p.p.","example":"You needn''t have brought wine — we had plenty."}],"examples":[{"en":"The lights are off. They must have gone to bed.","fr":"Les lumières sont éteintes. Ils ont dû aller se coucher."},{"en":"That can''t be the right address — it''s a car park.","fr":"Ça ne peut pas être la bonne adresse, c''est un parking."},{"en":"You could have hurt yourself!","fr":"Tu aurais pu te blesser !"},{"en":"You don''t have to come, but you mustn''t tell anyone.","fr":"Tu n''es pas obligé de venir, mais tu ne dois le dire à personne."}],"mistakes":[{"wrong":"He must forgot his keys.","right":"He must have forgotten his keys.","why":"Déduction au passé : must + have + participe passé."},{"wrong":"You mustn''t pay — it''s free.","right":"You don''t have to pay — it''s free.","why":"mustn''t = interdiction ; absence d''obligation = don''t have to."},{"wrong":"She can''t have be ill.","right":"She can''t have been ill.","why":"have est suivi du participe passé (been)."}]}'::jsonb),
  ('inversion', 'B2+', 'Inversion for emphasis', 'L''inversion emphatique', 'Mettre en relief avec Never have I…, Not only…, Had I known…', '{"explanationFr":["Après certains **adverbes négatifs ou restrictifs placés en tête de phrase**, l''anglais soutenu inverse le sujet et l''auxiliaire, comme dans une question : *Never have I seen such a mess.* Expressions courantes : *never, rarely, seldom, hardly … when, no sooner … than, not only … but also, under no circumstances, at no time, only then, only after, little*.","S''il n''y a pas d''auxiliaire, on ajoute **do / does / did** : *Rarely do we receive complaints.* *Little did she know that…*","**Inversion conditionnelle** (sans *if*) : *Had I known* (= If I had known), *Should you need help* (= If you need help), *Were it not for* (= If it weren''t for). C''est très fréquent dans les courriers formels : *Should you have any questions, please do not hesitate to contact me.*","L''inversion est un **outil de style** : elle apporte de la force à un essai ou un discours. Ne l''utilisez pas dans chaque phrase, ni dans une conversation détendue."],"explanationEn":["In formal or emphatic English, a negative or restrictive adverbial at the start of a clause triggers question-style inversion of subject and auxiliary.","Conditional inversion (Had I…, Should you…, Were it not for…) replaces if in formal registers."],"forms":[{"label":"Negative adverbial","pattern":"Never/Rarely/Seldom + aux + subject + verb","example":"Seldom have I felt so welcome."},{"label":"Not only","pattern":"Not only + aux + subject…, but … also","example":"Not only did he lie, but he also blamed me."},{"label":"Time sequence","pattern":"No sooner had + S + p.p. … than / Hardly had … when","example":"No sooner had we sat down than the fire alarm went off."},{"label":"Conditional","pattern":"Had / Should / Were + subject …","example":"Should you require assistance, call reception."}],"examples":[{"en":"Under no circumstances should you share your password.","fr":"Vous ne devez en aucun cas partager votre mot de passe."},{"en":"Only after the meeting did I realise my mistake.","fr":"Ce n''est qu''après la réunion que j''ai compris mon erreur."},{"en":"Had they invested earlier, they would have doubled their profits.","fr":"S''ils avaient investi plus tôt, ils auraient doublé leurs bénéfices."},{"en":"Little did we know what was about to happen.","fr":"Nous étions loin de nous douter de ce qui allait se passer."}],"mistakes":[{"wrong":"Never I have seen such a beautiful view.","right":"Never have I seen such a beautiful view.","why":"Après never en tête de phrase : auxiliaire + sujet."},{"wrong":"Not only he speaks French, but also German.","right":"Not only does he speak French, but he also speaks German.","why":"En tête de phrase, not only déclenche l''inversion avec do/does/did."},{"wrong":"No sooner had we arrived when it started raining.","right":"No sooner had we arrived than it started raining.","why":"no sooner … than ; hardly … when."}]}'::jsonb),
  ('cleft-sentences', 'B2+', 'Cleft sentences', 'Les phrases clivées (mise en relief)', 'It was… that… / What I need is… : mettre l''information importante en valeur.', '{"explanationFr":["Une phrase **clivée** découpe une phrase en deux pour mettre un élément en relief, comme le français « c''est … qui / que ». **It-cleft** : *It was Sarah who found the bug* (c''est Sarah qui…) ; *It''s the price that worries me.*","**Wh-cleft** (pseudo-clivée) : *What + proposition + be + élément mis en valeur*. *What I need is a holiday.* *What annoys me is his attitude.* Avec un verbe : *What she did was (to) call the police.*","Variantes utiles à l''oral et à l''écrit : *All I want is…* (tout ce que je veux), *The reason why … is that…*, *The thing (that) … is…*, *The place where…*, *It wasn''t until … that…* (ce n''est qu''à … que…).","Les clivées permettent aussi de **corriger** ou **contraster** : *It wasn''t the design that failed, it was the testing.*"],"explanationEn":["Cleft sentences split information to focus on one part. It-clefts (It is/was X that/who…) highlight a noun or adverbial; wh-clefts (What … is/was X) build suspense before the key information."],"forms":[{"label":"It-cleft","pattern":"It + be + focus + that/who + clause","example":"It was in 2015 that we launched the app."},{"label":"Wh-cleft","pattern":"What + clause + be + focus","example":"What surprised me was the silence."},{"label":"Action focus","pattern":"What + S + did + was + (to) verb","example":"What we did was rewrite the code."},{"label":"Not until","pattern":"It wasn''t until + time + that…","example":"It wasn''t until midnight that he called."}],"examples":[{"en":"It''s not the money that matters, it''s the experience.","fr":"Ce n''est pas l''argent qui compte, c''est l''expérience."},{"en":"What I love about this city is its energy.","fr":"Ce que j''adore dans cette ville, c''est son énergie."},{"en":"All we need is a bit more time.","fr":"Tout ce dont nous avons besoin, c''est d''un peu plus de temps."},{"en":"The reason why I left is that I wanted a new challenge.","fr":"La raison pour laquelle je suis parti, c''est que je voulais un nouveau défi."}],"mistakes":[{"wrong":"What I need it is a coffee.","right":"What I need is a coffee.","why":"Pas de pronom it supplémentaire dans une wh-cleft."},{"wrong":"It was my brother which called.","right":"It was my brother who called.","why":"Pour une personne : who (ou that)."},{"wrong":"The reason is because I was tired.","right":"The reason is that I was tired.","why":"The reason … is that (et non because) dans un style correct."}]}'::jsonb),
  ('linking-words', 'B2+', 'Advanced linking words', 'Connecteurs logiques avancés', 'Articuler un raisonnement : concession, cause, conséquence, contraste.', '{"explanationFr":["**Concession** : *although / even though / though* + proposition ; *despite / in spite of* + **nom ou -ing** (*despite the rain, despite being tired*, ou *despite the fact that* + proposition) ; *however* (adverbe : en début de phrase, suivi d''une virgule) ; *nevertheless / nonetheless* (néanmoins).","**Contraste** : *whereas / while* (tandis que) ; *on the other hand* (en revanche) ; *on the contrary* sert à **contredire** ce qui précède (au contraire), pas à comparer.","**Cause et conséquence** : *because of / due to / owing to* + nom ; *as / since* + proposition ; *therefore, consequently, as a result, thus, hence* (donc, par conséquent). **Ajout** : *moreover, furthermore, in addition, what is more*. **But** : *so that, in order to, so as not to*.","Attention à la **ponctuation** : *however* et *therefore* ne relient pas deux propositions avec une simple virgule. On écrit *…, but…* ou *…. However, …* ou *…; however, …*."],"explanationEn":["Advanced linkers signal the logic of an argument. Pay attention to grammar: although + clause, despite + noun/-ing; however and therefore are sentence adverbs, not conjunctions."],"forms":[{"label":"Concession + clause","pattern":"Although / Even though + S + V","example":"Although it was late, we kept working."},{"label":"Concession + noun","pattern":"Despite / In spite of + noun / -ing","example":"Despite the cost, the project went ahead."},{"label":"Sentence adverb","pattern":"S + V. However, / Therefore, S + V.","example":"Sales fell. However, profits rose."},{"label":"Purpose","pattern":"so that + S + can/could ; in order (not) to","example":"Speak slowly so that everyone can follow."}],"examples":[{"en":"Despite having little experience, she was hired.","fr":"Bien qu''elle ait peu d''expérience, elle a été embauchée."},{"en":"Some people love cities, whereas others prefer the countryside.","fr":"Certains adorent la ville, tandis que d''autres préfèrent la campagne."},{"en":"The flight was cancelled due to the storm.","fr":"Le vol a été annulé en raison de la tempête."},{"en":"The data is incomplete; therefore, no conclusion can be drawn.","fr":"Les données sont incomplètes ; on ne peut donc tirer aucune conclusion."}],"mistakes":[{"wrong":"Despite it was raining, we went out.","right":"Although it was raining, we went out. / Despite the rain, we went out.","why":"despite est suivi d''un nom ou d''un -ing, pas d''une proposition."},{"wrong":"I was tired, however I finished the report.","right":"I was tired. However, I finished the report.","why":"however n''est pas une conjonction : point (ou point-virgule) + virgule."},{"wrong":"He''s rich. On the contrary, his brother is poor.","right":"He''s rich. On the other hand, his brother is poor.","why":"on the contrary contredit ; on the other hand compare."}]}'::jsonb),
  ('punctuation-style', 'B2+', 'Punctuation and style', 'Ponctuation et style', 'Virgules, points-virgules, apostrophes, majuscules et registre.', '{"explanationFr":["La **comma splice** (deux phrases complètes reliées par une simple virgule) est l''erreur la plus fréquente des francophones : *It was late, we went home* ✗. Solutions : un point, un point-virgule, ou une conjonction (*It was late, so we went home*).","**Apostrophes** : possession (*the company''s profits*, singulier ; *the employees'' rights*, pluriel), contractions (*it''s = it is*). **its** (possessif) n''a jamais d''apostrophe. Les contractions sont à éviter dans un écrit formel.","**Majuscules** : en anglais, les jours, mois, langues, nationalités et adjectifs de nationalité prennent une majuscule : *Monday, March, French, a Spanish company*. Pas de majuscule aux saisons (*summer*).","**Style** : préférez la voix active quand l''agent compte, variez la longueur des phrases, évitez les répétitions, choisissez le **registre** adapté (*get → obtain/receive*, *a lot of → a significant number of*, *but → however*) et utilisez la virgule après une subordonnée en tête (*If you agree, …*). Pas d''espace avant ? ! : ; en anglais."],"explanationEn":["Avoid comma splices; use full stops, semicolons or conjunctions. Use apostrophes for possession and contractions, but not in its (possessive). Capitalise days, months, languages and nationalities.","Good style means choosing the right register, varying sentence length, and using punctuation to guide the reader."],"forms":[{"label":"Joining clauses","pattern":"Clause. Clause. / Clause; clause. / Clause, and/but/so clause.","example":"Sales rose; costs, however, rose faster."},{"label":"Possessive","pattern":"noun''s (singular) / nouns'' (plural)","example":"the manager''s office / the managers'' meeting"},{"label":"Intro clause","pattern":"Subordinate clause, main clause","example":"Although the plan is ambitious, it is realistic."}],"examples":[{"en":"The meeting is on Tuesday, 4 March.","fr":"La réunion a lieu le mardi 4 mars.","note":"majuscules"},{"en":"It''s clear that the company has lost its way.","fr":"Il est clair que l''entreprise a perdu son cap.","note":"it''s vs its"},{"en":"We missed the deadline; as a result, the client cancelled.","fr":"Nous avons raté la date limite ; le client a donc annulé."}],"mistakes":[{"wrong":"The results were good, we celebrated.","right":"The results were good, so we celebrated. / The results were good. We celebrated.","why":"Comma splice : deux phrases indépendantes ne se relient pas par une virgule seule."},{"wrong":"The company lost it''s biggest client.","right":"The company lost its biggest client.","why":"its (possessif) ne prend pas d''apostrophe."},{"wrong":"I speak english and spanish.","right":"I speak English and Spanish.","why":"Les langues prennent une majuscule."}]}'::jsonb),
  ('subjunctive', 'C1', 'The subjunctive and formal hypotheticals', 'Le subjonctif et l''irréel formel', 'It is essential that he be… / It''s high time we left / as if, would rather.', '{"explanationFr":["Le **subjonctif présent** anglais est simplement la **base verbale**, identique à toutes les personnes (pas de -s, *be* reste *be*). Il apparaît après des verbes et adjectifs de recommandation ou d''exigence : *suggest, recommend, insist, demand, request, propose* ; *essential, vital, crucial, important, imperative*. *The committee recommends that the policy **be** reviewed.* *It is vital that she **attend** the meeting.*","La négation se place avant la base verbale, sans *do* : *We insisted that he **not** be informed.* En anglais britannique courant, on utilise souvent *should* : *It is essential that she should attend.* L''indicatif (*that she attends*) existe à l''oral britannique mais reste moins soutenu.","Le **subjonctif passé / irréel** (*were* à toutes les personnes) : *If I were you…, as if he were the boss, I wish it were Friday.*","Structures d''irréel à connaître : **It''s (high / about) time + past simple** (*It''s high time we changed our approach* : il est grand temps que…) ; **would rather + sujet + past simple** (*I''d rather you didn''t smoke here*) ; **as if / as though** + past (*He talks as if he knew everything*) ; **suppose / supposing** + past (*Suppose you lost your job, what would you do?*)."],"explanationEn":["The mandative subjunctive uses the base form for all persons after verbs and adjectives of necessity or recommendation (insist, suggest, essential). Negatives use not + base form.","Unreal past forms follow it''s time, would rather (with a different subject), as if and wish."],"forms":[{"label":"Mandative","pattern":"suggest / insist / essential that + S + base verb","example":"They demanded that the CEO resign."},{"label":"Negative","pattern":"that + S + not + base verb","example":"I recommend that he not sign yet."},{"label":"It''s time","pattern":"It''s (high) time + S + past simple","example":"It''s high time you learnt to cook."},{"label":"Would rather","pattern":"would rather + S + past simple","example":"I''d rather you told me the truth."}],"examples":[{"en":"The doctor insisted that he rest for a week.","fr":"Le médecin a insisté pour qu''il se repose une semaine."},{"en":"It is imperative that every employee be trained.","fr":"Il est impératif que chaque salarié soit formé."},{"en":"It''s about time we went home.","fr":"Il serait temps qu''on rentre."},{"en":"She behaves as though nothing had happened.","fr":"Elle se comporte comme si de rien n''était."}],"mistakes":[{"wrong":"The board suggested that she resigns.","right":"The board suggested that she resign. / … that she should resign.","why":"Après suggest (recommandation), subjonctif (base verbale) ou should."},{"wrong":"It''s time we go.","right":"It''s time we went. / It''s time to go.","why":"It''s time + sujet + past simple (irréel)."},{"wrong":"I''d rather you don''t tell anyone.","right":"I''d rather you didn''t tell anyone.","why":"would rather + autre sujet + past simple."}]}'::jsonb),
  ('complex-sentences', 'C1', 'Complex sentences: participle clauses & nominalisation', 'Phrases complexes : participiales et nominalisation', 'Condenser l''information comme dans les textes académiques et professionnels.', '{"explanationFr":["Les **propositions participiales** condensent l''information. **-ing** pour une action simultanée ou active : *Walking into the room, she noticed the silence.* **Participe passé** pour un sens passif : *Built in 1890, the station is now a museum.* **Having + p.p.** pour l''antériorité : *Having finished the report, he went home.* Le sujet de la participiale doit être le même que celui de la principale, sinon c''est un *dangling participle* (erreur).","La **nominalisation** transforme verbes et adjectifs en noms, ce qui rend le style plus abstrait et formel : *The company expanded rapidly, which surprised analysts* → *The company''s rapid expansion surprised analysts.* Très utile en écriture académique, mais à doser pour rester lisible.","Autres outils de complexité : les relatives réduites (*the people living here* = who live here), *with + nom + -ing/p.p.* (*With prices rising, consumers are cutting back*), les propositions en *what* (*What matters is…*) et l''emboîtement de subordonnées.","Un texte C1 alterne phrases complexes et phrases courtes. La clarté prime : une idée principale par phrase."],"explanationEn":["Participle clauses (present, past and perfect) allow concise, sophisticated sentences, but the implied subject must match the subject of the main clause.","Nominalisation turns processes into nouns (decide → decision, increase → an increase), producing the dense style typical of academic and professional writing."],"forms":[{"label":"Present participle","pattern":"Verb-ing …, main clause","example":"Feeling unwell, she left early."},{"label":"Past participle","pattern":"P.p. …, main clause","example":"Written in plain English, the guide is easy to follow."},{"label":"Perfect participle","pattern":"Having + p.p. …, main clause","example":"Having lived abroad, he adapts quickly."},{"label":"Nominalisation","pattern":"verb/adj → noun phrase","example":"They failed to respond → Their failure to respond…"}],"examples":[{"en":"Having reviewed the evidence, the court dismissed the case.","fr":"Après avoir examiné les preuves, le tribunal a rejeté l''affaire."},{"en":"Founded in 1998, the company now employs 4,000 people.","fr":"Fondée en 1998, l''entreprise emploie aujourd''hui 4 000 personnes."},{"en":"The introduction of the new tax led to widespread protests.","fr":"L''introduction de la nouvelle taxe a entraîné de nombreuses manifestations.","note":"nominalisation"},{"en":"With unemployment falling, the government is under less pressure.","fr":"Avec la baisse du chômage, le gouvernement subit moins de pression."}],"mistakes":[{"wrong":"Walking down the street, the rain started.","right":"Walking down the street, I got caught in the rain. / As I was walking down the street, it started to rain.","why":"Dangling participle : ce n''est pas la pluie qui marche."},{"wrong":"Finishing the report, he sent it to his boss.","right":"Having finished the report, he sent it to his boss.","why":"Pour une action antérieure et achevée : having + p.p."},{"wrong":"The decide of the board was surprising.","right":"The decision of the board was surprising. / The board''s decision was surprising.","why":"Il faut le nom (decision), pas le verbe."}]}'::jsonb),
  ('nuances', 'C1', 'Grammatical nuance: hedging, distancing & habits', 'Nuances : atténuation, distance, habitudes', 'Nuancer une affirmation, prendre de la distance, parler d''habitudes passées et actuelles.', '{"explanationFr":["**Hedging (atténuation)** : en anglais académique et professionnel, on évite les affirmations trop catégoriques. Outils : modaux (*may, might, could*), verbes (*appear, seem, tend to, suggest, indicate*), adverbes (*arguably, possibly, largely, relatively*), expressions (*to some extent, it could be argued that*). *The results suggest that…* plutôt que *The results prove that…*.","**Distance et politesse** : le passé et le continu adoucissent une demande : *I was wondering if you could…*, *I was hoping to discuss…*, *Would you mind…?* Les tournures *It seems / It appears that…* prennent de la distance par rapport à une information.","**Habitudes** : *used to* (habitude ou état passé révolu : *I used to live in Nice*), *would* (habitude passée répétée, **pas pour les états** : *Every summer we would go camping* ; *I would have a dog* ✗), *be / get used to + -ing* (être / s''habituer à). Au présent, *will* et *keep + -ing* peuvent exprimer une habitude caractéristique ou agaçante : *He''ll sit there for hours*, *She keeps interrupting me*, *He''s always complaining*.","**Aspect et sens** : certains verbes d''état prennent un sens dynamique au continu : *I''m seeing a client* (rencontrer) / *I see what you mean* ; *She''s being difficult* (comportement temporaire) / *She is difficult* (caractère)."],"explanationEn":["Hedging language (may, appear, tend to, arguably, to some extent) allows you to make cautious, credible claims. Past and continuous forms create politeness and distance.","Used to describes past habits and states; would describes repeated past actions only. Always + continuous or keep + -ing express annoying habits."],"forms":[{"label":"Hedging","pattern":"seem/appear/tend + to ; may/might ; arguably","example":"This approach appears to reduce costs."},{"label":"Polite distance","pattern":"I was wondering if… / I was hoping…","example":"I was wondering if we could reschedule."},{"label":"Past habit","pattern":"used to + verb / would + verb (actions only)","example":"We used to live in Lille. We would walk to school."},{"label":"Annoying habit","pattern":"be always + -ing / keep + -ing","example":"He''s always leaving the door open."}],"examples":[{"en":"The findings would seem to indicate a link.","fr":"Les résultats sembleraient indiquer un lien.","note":"atténuation forte"},{"en":"It could be argued that the policy has largely failed.","fr":"On pourrait soutenir que la politique a en grande partie échoué."},{"en":"When I was a child, my grandfather would tell us stories every night.","fr":"Quand j''étais enfant, mon grand-père nous racontait des histoires tous les soirs."},{"en":"You''re being very quiet today. Is everything OK?","fr":"Tu es bien silencieux aujourd''hui. Tout va bien ?"}],"mistakes":[{"wrong":"When I was young, I would have long hair.","right":"When I was young, I used to have long hair.","why":"would ne s''emploie pas pour un état passé (have, be, live…)."},{"wrong":"This study proves that social media causes depression.","right":"This study suggests that social media may contribute to depression.","why":"En contexte académique, une affirmation trop forte n''est pas crédible : il faut nuancer."},{"wrong":"I''m not used to wake up early.","right":"I''m not used to waking up early.","why":"be used to + -ing."}]}'::jsonb)
