  ('listening:flat-viewing', 'listening', 'B1', null, null, 'Viewing a flat', '{"id":"flat-viewing","title":"Viewing a flat","level":"B1","genre":"conversation","context":"Chloe visits a flat in Manchester with the landlord, Mr Davies.","baseRate":0.9,"speakers":[{"name":"Mr Davies","accent":"en-GB","gender":"m"},{"name":"Chloe","accent":"en-GB","gender":"f"}],"lines":[{"speaker":0,"text":"Come in, come in. So, this is the living room. It gets a lot of light in the afternoon."},{"speaker":1,"text":"Oh, it''s bigger than it looked in the photos. Is the furniture included?"},{"speaker":0,"text":"Most of it, yes. The sofa and the table stay, but the previous tenant is taking the bookshelves."},{"speaker":1,"text":"That''s fine, I''ve got my own. And how much is the rent exactly? The advert said eight hundred and fifty."},{"speaker":0,"text":"That''s right, eight hundred and fifty a month, but that doesn''t include bills. Gas and electricity are usually around ninety pounds in winter."},{"speaker":1,"text":"OK. And is there a deposit?"},{"speaker":0,"text":"Yes, five weeks'' rent, which is protected in a government scheme, so you get it back when you leave, as long as there''s no damage."},{"speaker":1,"text":"Right. How far is it from the tram stop? I work in the city centre."},{"speaker":0,"text":"It''s a five-minute walk, and the tram gets you into town in about fifteen minutes."},{"speaker":1,"text":"That''s perfect. When would it be available?"},{"speaker":0,"text":"From the first of next month. But I''ve got two other people coming to see it tomorrow, so if you''re interested, let me know fairly quickly."},{"speaker":1,"text":"I''ll talk to my partner tonight and call you first thing tomorrow morning."}],"expressions":[{"en":"Is the furniture included?","fr":"Les meubles sont-ils compris ?"},{"en":"bills","fr":"les charges (gaz, électricité…)"},{"en":"a deposit","fr":"une caution, un dépôt de garantie"},{"en":"first thing tomorrow morning","fr":"demain à la première heure"}]}'::jsonb),
  ('listening:team-standup', 'listening', 'B1', null, null, 'Monday stand-up meeting', '{"id":"team-standup","title":"Monday stand-up meeting","level":"B1","genre":"professional","context":"A short team meeting at a software company in Boston.","baseRate":0.95,"speakers":[{"name":"Priya (team lead)","accent":"en-US","gender":"f"},{"name":"Marcus","accent":"en-US","gender":"m"},{"name":"Lena","accent":"intl","gender":"f"}],"lines":[{"speaker":0,"text":"Morning, everyone. Let''s keep this quick — we''ve got the client demo on Thursday. Marcus, do you want to start?"},{"speaker":1,"text":"Sure. Last week I finished the login page, and I''ve fixed most of the bugs the testers reported. Today I''m working on the password reset feature."},{"speaker":0,"text":"Great. Any blockers?"},{"speaker":1,"text":"Kind of. I''m still waiting for the new email templates from the design team, so I can''t test the whole flow yet."},{"speaker":0,"text":"OK, I''ll chase them after this meeting. Lena?"},{"speaker":2,"text":"I''ve been working on the dashboard. The charts are done, but the page loads too slowly — about six seconds. I think the problem is the database queries."},{"speaker":0,"text":"Six seconds is way too long for the demo. Can you and Marcus look at it together this afternoon?"},{"speaker":2,"text":"Yes, no problem. If we can''t fix it by Wednesday, we could show the client a version with sample data."},{"speaker":0,"text":"Good idea, let''s keep that as plan B. OK, so to sum up: Marcus on password reset, Lena and Marcus on performance this afternoon, and I''ll talk to design. Thanks, everyone."}],"expressions":[{"en":"Any blockers?","fr":"Des points bloquants ?"},{"en":"I''ll chase them.","fr":"Je vais les relancer."},{"en":"plan B","fr":"solution de repli"},{"en":"to sum up","fr":"pour résumer"}]}'::jsonb),
  ('listening:airport-problem', 'listening', 'B1+', null, null, 'A problem at the airport', '{"id":"airport-problem","title":"A problem at the airport","level":"B1+","genre":"conversation","context":"Tom''s flight has been cancelled. He talks to an airline agent at Dublin Airport.","baseRate":1,"speakers":[{"name":"Agent","accent":"intl","gender":"f"},{"name":"Tom","accent":"en-GB","gender":"m"}],"lines":[{"speaker":1,"text":"Hi. My flight to Lyon has just been cancelled, and nobody seems to know what''s going on."},{"speaker":0,"text":"I''m really sorry about that, sir. It''s due to the air traffic control strike in France. Could I see your booking reference?"},{"speaker":1,"text":"Here you go. I''ve got an important meeting tomorrow afternoon, so I really need to get there tonight if possible."},{"speaker":0,"text":"Let me check. Unfortunately, all our direct flights to Lyon today are cancelled. I could put you on a flight to Geneva at nine forty tonight. From there, it''s about two hours by train to Lyon."},{"speaker":1,"text":"Geneva… That could work. Would I have to pay for the train?"},{"speaker":0,"text":"Under EU rules, we''ll reimburse reasonable transport costs. Just keep your receipt and fill in the online claim form."},{"speaker":1,"text":"OK. And what about my suitcase? I''ve already checked it in."},{"speaker":0,"text":"It''ll be transferred automatically to the Geneva flight. You''ll collect it there."},{"speaker":1,"text":"Right. And I''ve been here since three o''clock — is there anything for food?"},{"speaker":0,"text":"Of course. Here''s a meal voucher for fifteen euros. You can use it at any restaurant after security."},{"speaker":1,"text":"Thanks. You''ve been very helpful — it''s not your fault, I know."}],"expressions":[{"en":"booking reference","fr":"numéro de réservation"},{"en":"we''ll reimburse","fr":"nous rembourserons"},{"en":"fill in a claim form","fr":"remplir un formulaire de réclamation"},{"en":"after security","fr":"après le contrôle de sécurité"}]}'::jsonb),
  ('listening:habits-podcast', 'listening', 'B1+', null, null, 'Podcast: Why habits fail', '{"id":"habits-podcast","title":"Podcast: Why habits fail","level":"B1+","genre":"podcast","context":"Two hosts of a self-improvement podcast discuss why New Year''s resolutions often fail.","baseRate":1,"speakers":[{"name":"Jake","accent":"en-US","gender":"m"},{"name":"Nora","accent":"en-US","gender":"f"}],"lines":[{"speaker":0,"text":"Welcome back to Small Steps. Nora, it''s February, which means most people have already given up on their New Year''s resolutions."},{"speaker":1,"text":"Right, and there''s actually research on this. One study found that about a quarter of people quit their resolutions within the first week."},{"speaker":0,"text":"Within a week! So what''s going wrong?"},{"speaker":1,"text":"The main problem is that people set goals that are way too big. ''I''m going to run every day'' or ''I''m going to learn Spanish this year.'' Those are outcomes, not habits."},{"speaker":0,"text":"So what should they do instead?"},{"speaker":1,"text":"Make the habit so small it''s almost ridiculous. Instead of running for an hour, just put your running shoes on every morning. Instead of learning Spanish, do five minutes on an app after breakfast."},{"speaker":0,"text":"I like the ''after breakfast'' part. You''re attaching the new habit to something you already do."},{"speaker":1,"text":"Exactly. Psychologists call it habit stacking. Your existing routine becomes the trigger. And the other key thing is to track it — even just a tick on a calendar. Seeing a chain of ticks is surprisingly motivating."},{"speaker":0,"text":"And if you miss a day?"},{"speaker":1,"text":"Never miss twice. Missing once is an accident. Missing twice is the start of a new habit — the wrong one."}],"expressions":[{"en":"to give up on something","fr":"renoncer à quelque chose"},{"en":"way too big","fr":"beaucoup trop ambitieux"},{"en":"the trigger","fr":"le déclencheur"},{"en":"surprisingly motivating","fr":"étonnamment motivant"}]}'::jsonb),
  ('listening:news-four-day-week', 'listening', 'B2', null, null, 'News report: the four-day week', '{"id":"news-four-day-week","title":"News report: the four-day week","level":"B2","genre":"news","context":"A radio news report from the UK about a four-day working week trial.","baseRate":1.05,"speakers":[{"name":"Newsreader","accent":"en-GB","gender":"f"},{"name":"Reporter","accent":"en-GB","gender":"m"},{"name":"Business owner","accent":"intl","gender":"f"}],"lines":[{"speaker":0,"text":"The results of the largest trial of a four-day working week have been published today. Our business correspondent has the details."},{"speaker":1,"text":"Sixty-one companies took part in the six-month experiment, with staff working four days a week for the same pay. At the end of the trial, fifty-six of them decided to continue, and eighteen made the change permanent."},{"speaker":1,"text":"According to the researchers, revenue stayed broadly the same during the trial, while the number of employees taking sick days fell by around two thirds. Staff reported lower levels of stress and burnout."},{"speaker":2,"text":"Honestly, I was sceptical at first. But we cut unnecessary meetings, we stopped answering emails all day, and productivity actually went up. Recruitment has also become much easier — candidates love it."},{"speaker":1,"text":"However, not everyone is convinced. Critics point out that most participating companies were small and worked in offices. They argue the model would be far harder to apply in sectors such as healthcare, retail or manufacturing, where services must be provided every day."},{"speaker":0,"text":"And is the government likely to act on these findings?"},{"speaker":1,"text":"Not in the short term. Ministers say they welcome the research but have no plans to change employment law. For now, it''s up to individual employers."}],"expressions":[{"en":"for the same pay","fr":"pour le même salaire"},{"en":"broadly the same","fr":"globalement inchangé"},{"en":"I was sceptical at first","fr":"j''étais sceptique au début"},{"en":"it''s up to individual employers","fr":"c''est à chaque employeur de décider"}]}'::jsonb),
  ('listening:job-interview', 'listening', 'B2', null, null, 'Job interview: project manager', '{"id":"job-interview","title":"Job interview: project manager","level":"B2","genre":"interview","context":"Daniel interviews Amira for a project manager position at a renewable energy company.","baseRate":1,"speakers":[{"name":"Daniel (interviewer)","accent":"en-GB","gender":"m"},{"name":"Amira (candidate)","accent":"intl","gender":"f"}],"lines":[{"speaker":0,"text":"Thanks for coming in, Amira. Let''s start with an easy one: why are you interested in this role?"},{"speaker":1,"text":"Well, I''ve spent the last five years managing IT projects in banking, and while I''ve learnt a lot, I''d like my work to have a more direct impact. Renewable energy is a sector I genuinely care about."},{"speaker":0,"text":"Can you tell me about a project that didn''t go to plan, and what you did?"},{"speaker":1,"text":"Sure. Two years ago, we were migrating a payment system, and halfway through, our main supplier went bankrupt. We were suddenly three months behind schedule."},{"speaker":1,"text":"Rather than panicking, I got the stakeholders together, we re-prioritised the features, and we delivered the essential part on time. The rest followed six weeks later."},{"speaker":0,"text":"Impressive. What would you say is your main weakness?"},{"speaker":1,"text":"I used to find it hard to delegate — I wanted to control everything. These days I''m much better at trusting my team, partly because I''ve seen how much more we achieve when people feel responsible."},{"speaker":0,"text":"This role involves a lot of travel to wind farms in Scotland. Would that be a problem?"},{"speaker":1,"text":"Not at all. Actually, I''d see it as an advantage — I think you only really understand a project when you''ve seen it on the ground."},{"speaker":0,"text":"Great. Do you have any questions for us?"},{"speaker":1,"text":"Yes — how do you measure success for this role in the first six months?"}],"expressions":[{"en":"a project that didn''t go to plan","fr":"un projet qui ne s''est pas déroulé comme prévu"},{"en":"behind schedule","fr":"en retard sur le planning"},{"en":"on the ground","fr":"sur le terrain"},{"en":"I genuinely care about…","fr":"… me tient vraiment à cœur"}]}'::jsonb),
  ('listening:supplier-negotiation', 'listening', 'B2+', null, null, 'Negotiating with a supplier', '{"id":"supplier-negotiation","title":"Negotiating with a supplier","level":"B2+","genre":"professional","context":"A purchasing manager negotiates a contract renewal with a packaging supplier by video call.","baseRate":1,"speakers":[{"name":"Sophie (buyer)","accent":"en-GB","gender":"f"},{"name":"Raj (supplier)","accent":"intl","gender":"m"}],"lines":[{"speaker":1,"text":"So, as I mentioned in my email, because of the rise in raw material costs, we''d need to increase our prices by eight per cent from January."},{"speaker":0,"text":"I appreciate your transparency, Raj, but eight per cent is simply not something we can absorb. We''ve had competing offers that are actually below your current price."},{"speaker":1,"text":"I understand. But you also know our delivery record — we haven''t missed a single deadline in three years. Not every supplier can say that."},{"speaker":0,"text":"That''s true, and that''s why we''d like to continue working with you. So let''s see if we can find something that works for both of us. What if we committed to a two-year contract instead of one?"},{"speaker":1,"text":"That would certainly help with our planning. On a two-year basis, I could probably bring it down to five per cent."},{"speaker":0,"text":"If we also increase our order volume by around fifteen per cent, could you go to three?"},{"speaker":1,"text":"Three is tight… I''d need to check with my director. Could we say four, with payment within thirty days rather than sixty?"},{"speaker":0,"text":"Four with thirty-day payment terms… I think I can sell that internally. Send me a revised proposal and we''ll go through the details on Friday."},{"speaker":1,"text":"Sounds good. I''ll have it to you by Thursday."}],"expressions":[{"en":"something we can absorb","fr":"quelque chose que nous pouvons encaisser / supporter"},{"en":"something that works for both of us","fr":"une solution qui convienne aux deux parties"},{"en":"bring it down to…","fr":"le ramener à…"},{"en":"I can sell that internally","fr":"je peux le faire accepter en interne"}]}'::jsonb),
  ('listening:debate-cars-city', 'listening', 'B2+', null, null, 'Debate: should cars be banned from city centres?', '{"id":"debate-cars-city","title":"Debate: should cars be banned from city centres?","level":"B2+","genre":"debate","context":"A local radio debate between a city councillor and a shop owners'' representative.","baseRate":1.05,"speakers":[{"name":"Host","accent":"en-GB","gender":"m"},{"name":"Councillor Hayes","accent":"en-GB","gender":"f"},{"name":"Mr Ortiz","accent":"en-US","gender":"m"}],"lines":[{"speaker":0,"text":"The council wants to ban private cars from the historic centre by 2027. Councillor Hayes, why?"},{"speaker":1,"text":"Quite simply because our air is making people ill. Nitrogen dioxide levels in the centre regularly exceed legal limits. Cities that have done this — Ghent, Pontevedra — have seen cleaner air, fewer accidents and, crucially, more people walking into shops, not fewer."},{"speaker":0,"text":"Mr Ortiz, you represent local businesses. Are you persuaded?"},{"speaker":2,"text":"With respect, no. Those examples are cherry-picked. Pontevedra is a small town. Many of our customers are elderly or come from villages with no public transport. If they can''t park, they''ll simply drive to the out-of-town shopping centre instead."},{"speaker":1,"text":"Nobody is suggesting we abandon those customers. The plan includes park-and-ride sites, free shuttle buses and exemptions for disabled drivers and deliveries."},{"speaker":2,"text":"Plans are one thing. But when the roadworks start, it''s shops like mine that''ll pay the price. Some won''t survive two years of disruption."},{"speaker":0,"text":"So is there any middle ground?"},{"speaker":2,"text":"A phased approach. Start with car-free weekends, measure the impact on footfall, and then decide. That''s all we''re asking for."},{"speaker":1,"text":"I''m actually not opposed to a pilot phase, as long as it''s not used as an excuse to delay indefinitely. Public health can''t wait forever."}],"expressions":[{"en":"with respect, …","fr":"sauf votre respect, …"},{"en":"cherry-picked","fr":"choisi de façon sélective / partiale"},{"en":"pay the price","fr":"en payer le prix"},{"en":"is there any middle ground?","fr":"y a-t-il un compromis possible ?"},{"en":"footfall","fr":"fréquentation (nombre de passants / clients)"}]}'::jsonb),
  ('listening:lecture-memory', 'listening', 'C1', null, null, 'Lecture: how memory really works', '{"id":"lecture-memory","title":"Lecture: how memory really works","level":"C1","genre":"lecture","context":"Extract from an introductory cognitive psychology lecture at a university.","baseRate":1.05,"speakers":[{"name":"Dr Okafor","accent":"intl","gender":"m"}],"lines":[{"speaker":0,"text":"Today I want to challenge a metaphor most of you probably hold without realising it: the idea that memory works like a video recorder, faithfully storing events so that we can play them back later."},{"speaker":0,"text":"In reality, remembering is a reconstructive process. Each time you recall an event, you rebuild it from fragments, and in doing so you can alter it. This is why eyewitness testimony, however confident, is notoriously unreliable."},{"speaker":0,"text":"Elizabeth Loftus demonstrated this in the 1970s. Participants watched a film of a car accident and were then asked how fast the cars were going when they either ''hit'' or ''smashed into'' each other. Those who heard ''smashed'' gave higher estimates, and a week later they were more than twice as likely to report seeing broken glass, although there was none."},{"speaker":0,"text":"Now, the implications for learning are significant. If memory is reconstructive, then the act of retrieval itself strengthens it. Rereading your notes feels productive — the material looks familiar — but familiarity is not the same as being able to recall. Testing yourself, on the other hand, forces reconstruction, and that is precisely what consolidates the memory."},{"speaker":0,"text":"Combine retrieval practice with spacing — reviewing material at increasing intervals — and you have arguably the two most robust findings in the entire field of educational psychology."},{"speaker":0,"text":"For next week, I''d like you to read chapter four, and, rather than highlighting, close the book after each section and write down everything you can remember."}],"expressions":[{"en":"a reconstructive process","fr":"un processus de reconstruction"},{"en":"notoriously unreliable","fr":"notoirement peu fiable"},{"en":"the implications are significant","fr":"les implications sont importantes"},{"en":"arguably the most robust findings","fr":"sans doute les résultats les plus solides"}]}'::jsonb),
  ('listening:seminar-cities', 'listening', 'C1', null, null, 'Seminar: the 15-minute city', '{"id":"seminar-cities","title":"Seminar: the 15-minute city","level":"C1","genre":"academic","context":"Three postgraduate students discuss an urban planning concept in a seminar.","baseRate":1.1,"speakers":[{"name":"Hannah","accent":"en-US","gender":"f"},{"name":"Kwame","accent":"intl","gender":"m"},{"name":"Oliver","accent":"en-GB","gender":"m"}],"lines":[{"speaker":0,"text":"So the core premise of the fifteen-minute city is that residents should be able to reach most daily necessities — work, school, healthcare, shops — within a fifteen-minute walk or cycle."},{"speaker":1,"text":"Which sounds uncontroversial in principle. What I find striking, though, is how polarised the debate has become online. Some people genuinely believe it''s a plot to restrict their freedom of movement."},{"speaker":2,"text":"I think we should distinguish between the conspiracy theories, which are frankly baseless, and some legitimate criticisms. One is gentrification: once a neighbourhood becomes very convenient, property prices rise and the people it was meant to serve get priced out."},{"speaker":0,"text":"That''s a fair point, but it''s not unique to this model. Any improvement to a neighbourhood — a new metro line, a park — has that effect unless it''s accompanied by housing policy."},{"speaker":1,"text":"Agreed. I''d add that the concept was designed with dense European cities in mind. Transplanting it to a sprawling, car-dependent city is a different challenge altogether — you can''t retrofit density overnight."},{"speaker":2,"text":"So perhaps the question isn''t whether the model is good or bad, but under what conditions it''s achievable and equitable."},{"speaker":0,"text":"Which might make a good research question for our group paper, actually."}],"expressions":[{"en":"the core premise","fr":"le principe fondamental"},{"en":"uncontroversial in principle","fr":"consensuel sur le principe"},{"en":"get priced out","fr":"être chassé par la hausse des prix"},{"en":"a different challenge altogether","fr":"un tout autre défi"},{"en":"achievable and equitable","fr":"réalisable et équitable"}]}'::jsonb),
  ('listening:x-b1-listening', 'listening', 'B1', null, null, 'Planning a birthday surprise', '{"id":"x-b1-listening","title":"Planning a birthday surprise","level":"B1","genre":"conversation","context":"Two friends plan a surprise party.","baseRate":0.95,"speakers":[{"name":"Ella","accent":"en-GB","gender":"f"},{"name":"Ben","accent":"en-GB","gender":"m"}],"lines":[{"speaker":0,"text":"Ben, have you thought about Maya''s birthday? It''s on the twentieth."},{"speaker":1,"text":"I have! I thought we could have a surprise party at my place on the Saturday before, the eighteenth."},{"speaker":0,"text":"Great idea. But your flat''s quite small. How many people are you thinking of inviting?"},{"speaker":1,"text":"About fifteen. My flatmate will be away, so we''ll have the living room and the kitchen."},{"speaker":0,"text":"OK. I can make a cake — chocolate, because she hates fruit cakes."},{"speaker":1,"text":"Perfect. I''ll organise the music. How do we get her there without her guessing?"},{"speaker":0,"text":"I''ll tell her we''re going to the cinema and that I need to pick something up from your flat first."},{"speaker":1,"text":"Brilliant. Let''s say everyone arrives at seven and you bring her at half past."}],"expressions":[{"en":"without her guessing","fr":"sans qu''elle devine"}]}'::jsonb),
  ('listening:x-b2-listening', 'listening', 'B2', null, null, 'Radio interview: a rewilding project', '{"id":"x-b2-listening","title":"Radio interview: a rewilding project","level":"B2","genre":"interview","context":"A radio presenter talks to an ecologist about reintroducing beavers.","baseRate":1.05,"speakers":[{"name":"Presenter","accent":"en-GB","gender":"f"},{"name":"Dr Hale","accent":"en-GB","gender":"m"}],"lines":[{"speaker":0,"text":"Dr Hale, your team reintroduced beavers to this valley five years ago. Why beavers?"},{"speaker":1,"text":"Because they''re what we call ecosystem engineers. By building dams, they create wetlands, which slow down water during heavy rain and store it during droughts."},{"speaker":0,"text":"And has it worked?"},{"speaker":1,"text":"Remarkably well. Flooding in the village downstream has been reduced, and we''ve recorded a big increase in frogs, insects and birds."},{"speaker":0,"text":"Not everyone is happy, though. Some farmers say beavers have damaged their fields."},{"speaker":1,"text":"That''s a fair concern, and we take it seriously. In a few places, dams have flooded farmland. We now have a management plan — we can lower a dam or, as a last resort, move a family of beavers."},{"speaker":0,"text":"Would you recommend other regions do the same?"},{"speaker":1,"text":"Yes, but only with proper consultation. The biggest lesson we''ve learnt is that the ecology is the easy part; the hard part is people."}],"expressions":[{"en":"as a last resort","fr":"en dernier recours"}]}'::jsonb),
  ('listening:x-c1-listening', 'listening', 'C1', null, null, 'Panel discussion: the future of the office', '{"id":"x-c1-listening","title":"Panel discussion: the future of the office","level":"C1","genre":"debate","context":"Two experts discuss office design after the rise of remote work.","baseRate":1.1,"speakers":[{"name":"Chair","accent":"en-US","gender":"f"},{"name":"Ruth (architect)","accent":"en-GB","gender":"f"},{"name":"Tariq (economist)","accent":"intl","gender":"m"}],"lines":[{"speaker":0,"text":"Ruth, are we witnessing the end of the office?"},{"speaker":1,"text":"I''d say we''re witnessing the end of the office as a place where you go simply because you''re expected to. What survives will have to justify itself — as a place for collaboration, mentoring, and the kind of chance encounters that video calls can''t replicate."},{"speaker":2,"text":"I''d push back slightly on the romanticism of chance encounters. The data on so-called serendipity is thin. What we can measure is that junior staff, in particular, learn faster when they''re physically near experienced colleagues — that''s the strongest economic case for the office."},{"speaker":1,"text":"Which is essentially my point, though — that''s a design brief. If learning is the purpose, you design for overhearing, for visibility, not for rows of identical desks."},{"speaker":2,"text":"Granted. My concern is cost. Companies are holding leases on buildings that are half empty on Fridays. Unless they consolidate, the economics simply don''t add up."},{"speaker":0,"text":"So smaller, but better?"},{"speaker":1,"text":"Smaller, better, and — dare I say — more honest about what it''s for."}],"expressions":[{"en":"I''d push back slightly on…","fr":"je nuancerais un peu…"},{"en":"the economics don''t add up","fr":"les comptes ne tiennent pas"}]}'::jsonb),
  ('reading:repair-cafe', 'reading', 'B1', null, null, 'The Repair Café', '{"id":"repair-cafe","title":"The Repair Café","level":"B1","genre":"story","intro":"A short story about a neighbourhood initiative.","paragraphs":["When Martha''s toaster stopped working, her first thought was to buy a new one. It was only six years old, but that seemed normal: things break, and you replace them. Then her neighbour, Samir, told her about the Repair Café that had opened in the community centre at the end of their street.","Every second Saturday, a group of volunteers sets up tables with tools, sewing machines and soldering irons. Anyone can bring something that is broken — a lamp, a jacket, a bicycle, a laptop — and fix it with the help of an expert. The service is free, although most visitors leave a small donation for coffee and spare parts.","Martha was nervous when she arrived. She had never opened an electrical appliance in her life. A retired engineer called Frank showed her how to unscrew the base of the toaster safely. After ten minutes, they found the problem: a tiny wire had come loose. Frank let Martha reconnect it herself. When the toaster clicked and the coils turned orange, several people at the next table clapped.","\"The point isn''t just to save money,\" Frank explained over a cup of tea. \"Every object we repair is one less thing in the bin. And people discover they''re capable of more than they think.\" Since it opened two years ago, the café has repaired more than 1,400 items, according to its records.","Martha now volunteers there herself. She has learnt to fix zips and replace bicycle brakes, and she has made friends with people she had walked past for years without saying hello. \"I came for a toaster,\" she says, \"and I found a community.\""],"summaryTask":{"instruction":"Summarise the story in 3–4 sentences in English.","minWords":40,"maxWords":70},"keyVocab":[{"term":"appliance","meaning":"appareil électroménager"},{"term":"come loose","meaning":"se desserrer, se détacher"},{"term":"spare parts","meaning":"pièces détachées"},{"term":"volunteer","meaning":"bénévole ; faire du bénévolat"}]}'::jsonb),
  ('reading:teen-sleep', 'reading', 'B1', null, null, 'Should school start later?', '{"id":"teen-sleep","title":"Should school start later?","level":"B1","genre":"news","intro":"A news article about school start times.","paragraphs":["Teenagers are often accused of being lazy when they struggle to get out of bed in the morning. But scientists say the problem is biological, not a question of character. During adolescence, the body starts producing melatonin — the hormone that makes us feel sleepy — about two hours later than in childhood. As a result, many teenagers simply cannot fall asleep before eleven o''clock at night.","If school starts at eight, a student who needs to leave home at seven gets, at best, eight hours of sleep, while experts recommend between eight and ten for this age group. Over weeks and months, this lack of sleep can affect concentration, mood and even physical health.","Some schools have decided to act. In one district in the United States, secondary schools moved their start time from 7.50 to 8.45. Two years later, attendance had improved and the number of students falling asleep in class had dropped. Teachers also reported fewer arguments and better behaviour.","However, changing the timetable is not always easy. Parents who work early may not be able to drop their children off later, and buses are often shared between primary and secondary schools. Some critics also argue that teenagers would simply go to bed even later.","Researchers disagree. Studies show that when school starts later, students do not go to bed much later — they actually get more sleep. For many health experts, the evidence is now clear enough: our school day should be designed around how the teenage brain really works."],"summaryTask":{"instruction":"Summarise the main argument and one counter-argument in 3–4 sentences.","minWords":40,"maxWords":70},"keyVocab":[{"term":"struggle to","meaning":"avoir du mal à"},{"term":"attendance","meaning":"assiduité, présence"},{"term":"drop someone off","meaning":"déposer quelqu''un"},{"term":"evidence","meaning":"preuves, données"}]}'::jsonb),
  ('reading:remote-policy', 'reading', 'B1+', null, null, 'Internal memo: hybrid working policy', '{"id":"remote-policy","title":"Internal memo: hybrid working policy","level":"B1+","genre":"professional","intro":"An internal memo sent to all employees of a mid-sized company.","paragraphs":["To: All staff\nFrom: Human Resources\nSubject: Updated hybrid working policy — effective 1 March","Following the staff survey carried out in December, in which 82% of employees said they wanted to keep some form of remote work, the management team has agreed on a new hybrid policy. We would like to thank everyone who took part in the survey; your feedback has directly shaped the decisions below.","From 1 March, all office-based employees will be expected to work on site at least two days per week. One of these days will be a ''team day'', chosen by each department, so that colleagues can meet in person. The other days may be worked from home, subject to your manager''s approval.","Please note that this policy does not apply to staff in the warehouse and customer reception, whose roles require a physical presence. We are aware that this may feel unfair, and we are currently exploring other forms of flexibility for these teams, such as compressed hours.","Employees working from home must have a suitable workspace and a secure internet connection. The company will contribute €30 per month towards home-working costs, paid with your salary. Equipment such as laptops and headsets will continue to be provided by IT.","The policy will be reviewed in September. If you have any questions or concerns, please contact your HR business partner or attend one of the information sessions, which will be held on 14 and 21 February."],"summaryTask":{"instruction":"Write a short message (3–4 sentences) to a colleague explaining the main changes.","minWords":40,"maxWords":80},"keyVocab":[{"term":"effective (date)","meaning":"en vigueur à partir de"},{"term":"subject to","meaning":"sous réserve de"},{"term":"compressed hours","meaning":"semaine de travail compressée"},{"term":"on site","meaning":"sur place"}]}'::jsonb),
  ('reading:fast-fashion', 'reading', 'B2', null, null, 'The true cost of a cheap T-shirt', '{"id":"fast-fashion","title":"The true cost of a cheap T-shirt","level":"B2","genre":"news","intro":"A feature article about the environmental and social impact of fast fashion.","paragraphs":["A T-shirt for five euros seems like a bargain. But economists have a name for the costs that don''t appear on the price tag: externalities. In the case of fast fashion, they are considerable, and someone, somewhere, is paying them.","Consider water. Growing enough cotton for a single T-shirt can require around 2,700 litres, roughly what one person drinks in two and a half years. Much of the world''s cotton is grown in regions already facing water shortages. Then there is dyeing, which in some countries releases untreated chemicals directly into rivers, turning them unnatural shades of blue and red.","The human cost is equally significant. The collapse of the Rana Plaza factory building in Bangladesh in 2013, which killed more than 1,100 garment workers, drew global attention to unsafe working conditions. Since then, safety agreements have improved standards in many factories, yet wages in the sector often remain far below what campaigners consider a living wage.","Perhaps the most striking change, however, is the sheer quantity of clothing we buy. Shoppers in Europe purchase significantly more garments than they did two decades ago, and keep them for a much shorter time. Some items are worn only a handful of times before being thrown away. Contrary to popular belief, most donated clothes are not resold locally: a large share is exported, and a considerable proportion ends up in landfill.","Brands have responded with ''conscious'' collections and recycling schemes. Critics, however, warn that such initiatives can amount to greenwashing if overall production keeps rising. Truly recycling textiles into new fibres remains technically difficult, and only a tiny fraction of clothing is currently recycled in this way.","None of this means consumers must stop buying clothes. But the most sustainable garment, as many designers now admit, is the one already in your wardrobe. Buying less, choosing better quality, repairing and buying second-hand are, for now, far more effective than any label claiming to be green."],"summaryTask":{"instruction":"Summarise the article in 80–120 words, covering environmental, social and consumer aspects.","minWords":80,"maxWords":120},"keyVocab":[{"term":"bargain","meaning":"bonne affaire"},{"term":"garment","meaning":"vêtement (formel)"},{"term":"living wage","meaning":"salaire décent"},{"term":"landfill","meaning":"décharge"},{"term":"amount to","meaning":"revenir à, équivaloir à"}]}'::jsonb),
  ('reading:recommendation-algorithms', 'reading', 'B2', null, null, 'Who decides what you watch?', '{"id":"recommendation-algorithms","title":"Who decides what you watch?","level":"B2","genre":"tech","intro":"An explanatory article about recommendation algorithms.","paragraphs":["Every time you open a streaming or social media app, an algorithm has already decided what you will see first. These recommendation systems are among the most influential pieces of software ever written, yet most users have only a vague idea of how they work.","At their core, they are prediction machines. By analysing what you have watched, liked, skipped or paused, and comparing it with the behaviour of millions of other users, the system estimates the probability that you will engage with a particular item. Items with the highest predicted engagement are pushed to the top of your feed.","The key word is engagement. Platforms typically earn money from advertising or subscriptions, so their priority is to keep you on the app for as long as possible. This is not necessarily sinister: if you enjoy cooking videos, being shown more cooking videos is convenient. The problem arises when the content that maximises engagement is not the content that is good for us.","Research suggests that emotionally charged content — particularly content that provokes outrage — tends to generate more reactions and shares. An algorithm optimised purely for engagement may therefore end up amplifying divisive material, not because anyone designed it to, but because that is what the data rewarded.","In response, regulators in the European Union now require very large platforms to explain the main parameters of their recommendation systems and to offer at least one option that is not based on profiling. Whether users will actually choose such options is another question: a chronological feed is more transparent, but many people find it less entertaining.","Ultimately, recommendation algorithms reflect the goals of those who build them. Asking what a system is optimised for is perhaps the most useful question a user can ask."],"summaryTask":{"instruction":"Summarise how recommendation algorithms work and one risk they pose (60–100 words).","minWords":60,"maxWords":100},"keyVocab":[{"term":"engage with","meaning":"interagir avec"},{"term":"outrage","meaning":"indignation"},{"term":"divisive","meaning":"qui divise, clivant"},{"term":"profiling","meaning":"profilage"}]}'::jsonb),
  ('reading:in-praise-of-boredom', 'reading', 'B2+', null, null, 'In praise of boredom', '{"id":"in-praise-of-boredom","title":"In praise of boredom","level":"B2+","genre":"essay","intro":"An opinion essay.","paragraphs":["There was a time when waiting for a bus meant staring at the street, reading the same advertisement for the tenth time, or simply letting one''s mind wander. Today, those empty minutes have all but disappeared. The moment we feel the faintest hint of boredom, we reach for our phones. We have, in effect, eliminated one of the most common human experiences — and I am not convinced we should celebrate.","Boredom has a bad reputation. It is associated with idleness, with wasted time, with the restless child complaining that there is ''nothing to do''. Yet psychologists increasingly regard it not as a defect but as a signal: a sign that our current activity is failing to satisfy us, and a push to look for something more meaningful.","Several studies have found that people who were first given a deliberately dull task — copying numbers from a phone book, for instance — subsequently performed better on tests of creative thinking than those who had not been bored. The explanation seems to be that boredom encourages daydreaming, and daydreaming allows the mind to make unexpected connections.","It would be naive, of course, to romanticise boredom. Chronic boredom, particularly in work or school environments that offer no autonomy, is linked to stress and disengagement. The boredom I am defending is of a different kind: the brief, unstructured pause that we now fill instinctively with notifications.","What is lost when every gap is filled? Perhaps nothing dramatic. But it is worth asking whether our constant stimulation leaves enough room for reflection, for the slow forming of ideas, for the unplanned thought that turns out to matter. The next time you are waiting in a queue, you might try something radical: doing nothing at all."],"summaryTask":{"instruction":"Summarise the writer''s argument, including the concession, in 80–110 words.","minWords":80,"maxWords":110},"keyVocab":[{"term":"let one''s mind wander","meaning":"laisser vagabonder son esprit"},{"term":"idleness","meaning":"oisiveté"},{"term":"daydreaming","meaning":"rêverie"},{"term":"romanticise","meaning":"idéaliser"}]}'::jsonb),
  ('reading:gut-microbiome', 'reading', 'C1', null, null, 'The second brain? Reassessing the gut microbiome', '{"id":"gut-microbiome","title":"The second brain? Reassessing the gut microbiome","level":"C1","genre":"science","intro":"A science feature from a popular science magazine.","paragraphs":["Few areas of biology have generated as much excitement — or as many supplements — as research into the gut microbiome, the trillions of bacteria, fungi and viruses that inhabit our digestive system. Headlines have linked it to everything from obesity and allergies to depression and autism. The reality, as is often the case, is considerably more nuanced.","That the microbiome matters is beyond dispute. Gut bacteria help break down fibre that our own enzymes cannot digest, producing short-chain fatty acids that nourish the cells lining the intestine. They train the immune system in early life and occupy ecological niches that might otherwise be colonised by harmful microbes. Patients with recurrent infections of the bacterium *Clostridioides difficile*, for instance, can be cured with remarkable success by a transplant of faecal matter from a healthy donor.","The more speculative claims concern the so-called gut–brain axis. Experiments in which mice raised without any bacteria displayed altered stress responses were genuinely striking, and transferring microbes from anxious mice appeared to make calm mice more anxious. Extrapolating from such findings to humans, however, is fraught with difficulty. Laboratory mice differ from us in diet, physiology and, crucially, in the extent to which their environment can be controlled.","In human studies, the problem is largely one of causality. People with depression may indeed have different gut bacteria, but they also tend to eat differently, sleep differently and take medication — all of which alter the microbiome. Distinguishing cause from consequence requires long-term intervention trials, which remain comparatively scarce and frequently small.","None of this is to dismiss the field, which is arguably still in its infancy. Rather, it is a reminder that a promising correlation is a starting point for research, not a basis for marketing. For the time being, the dietary advice supported by the strongest evidence is reassuringly unglamorous: eat a varied diet rich in fibre, and be sceptical of any product promising to ''reset'' your gut."],"summaryTask":{"instruction":"Write a 100–130 word summary distinguishing established findings from speculative claims.","minWords":100,"maxWords":130},"keyVocab":[{"term":"beyond dispute","meaning":"incontestable"},{"term":"fraught with","meaning":"chargé de, plein de (problèmes)"},{"term":"in its infancy","meaning":"à ses débuts"},{"term":"scarce","meaning":"rare, peu nombreux"}]}'::jsonb),
  ('reading:machine-translation', 'reading', 'C1', null, null, 'Will machine translation make language learning obsolete?', '{"id":"machine-translation","title":"Will machine translation make language learning obsolete?","level":"C1","genre":"academic","intro":"Extract from an academic article in applied linguistics.","paragraphs":["The rapid improvement of neural machine translation has prompted a recurring question in public debate: if a device can render speech instantly into another language, why should anyone invest years in learning one? This article argues that the question rests on a reductive conception of what language competence entails.","It is undeniable that translation tools have become remarkably effective for transactional purposes — ordering food, reading a menu, understanding a contract''s general meaning. For many users, this is precisely what is needed, and the democratising effect of such tools should not be underestimated.","Communication, however, is not merely the transfer of propositional content. A considerable proportion of meaning is conveyed through pragmatics: what is implied rather than said, the degree of politeness or irony, the cultural associations of a particular word. Machine systems have made progress in these areas, yet they remain prone to errors precisely where stakes are highest — in negotiation, in humour, in emotionally sensitive exchanges.","Furthermore, mediated conversation alters the interaction itself. Speakers relying on a device tend to simplify their utterances, pause more and avoid spontaneous turn-taking. The resulting exchanges, while functional, often lack the rapport that characterises direct communication. In professional contexts, this deficit may carry tangible costs: trust, after all, is seldom built through an intermediary.","Finally, learning a language has cognitive and identity-related dimensions that no tool can replicate. Learners gain access to ways of perceiving and categorising experience that differ from those encoded in their first language. To treat language learning solely as a means of information exchange is therefore to overlook much of its value.","It follows that the role of language education is likely to shift rather than disappear. Instruction may place greater emphasis on intercultural competence, pragmatic awareness and critical use of the very tools that were expected to make it redundant."],"summaryTask":{"instruction":"Summarise the author''s argument in 100–130 words, using your own words as far as possible.","minWords":100,"maxWords":130},"keyVocab":[{"term":"entail","meaning":"impliquer, comporter"},{"term":"pragmatics","meaning":"pragmatique (sens implicite en contexte)"},{"term":"rapport","meaning":"relation de confiance, entente"},{"term":"tangible","meaning":"concret, palpable"}]}'::jsonb),
  ('reading:x-b1-reading', 'reading', 'B1', null, null, 'Volunteer at the City Farm', '{"id":"x-b1-reading","title":"Volunteer at the City Farm","level":"B1","genre":"news","intro":"An advert in a local newspaper.","paragraphs":["Hillside City Farm is looking for volunteers to help this summer. No experience is needed — just enthusiasm and a love of animals!","Volunteers usually work one morning or afternoon a week. Tasks include feeding the goats and chickens, cleaning the stables and helping visitors, especially school groups. Some volunteers also help in our café, where we sell vegetables grown on the farm.","You must be at least 16 years old. Volunteers under 18 need a signed form from a parent. Please wear old clothes and strong shoes; we provide gloves and waterproof jackets.","In return, you''ll get free lunch on the days you work, a reference letter after three months, and a 20% discount in the café. To apply, fill in the form on our website before 15 May. A short training session will take place on Saturday 1 June."],"summaryTask":{"instruction":"","minWords":0,"maxWords":0},"keyVocab":[]}'::jsonb),
  ('reading:x-b2-reading', 'reading', 'B2', null, null, 'The rise of ''quiet quitting''', '{"id":"x-b2-reading","title":"The rise of ''quiet quitting''","level":"B2","genre":"news","intro":"A magazine article.","paragraphs":["The phrase ''quiet quitting'' spread rapidly across social media a few years ago, and it has proved surprisingly durable. Despite its name, it does not involve resigning. Instead, it describes employees who do exactly what their job description requires — and nothing more.","Supporters argue that this is simply a healthy response to a culture of overwork. For years, they say, employees have been expected to answer emails late at night, take on extra responsibilities without extra pay, and treat their jobs as an identity rather than a contract. Setting boundaries, in this view, is not laziness but self-respect.","Critics, however, see something more worrying. They argue that careers are built on going beyond the minimum, and that workers who disengage may find themselves overlooked for promotion. Some managers also point out that teams depend on informal goodwill: covering for a sick colleague, sharing knowledge, helping a newcomer.","Perhaps the most interesting aspect of the debate is what it reveals about expectations. Surveys suggest that many employees who describe themselves as quiet quitters are not lazy at all; they feel undervalued. When their efforts were recognised, many said, they would happily do more. The solution, then, may lie less in changing workers'' attitudes than in changing how organisations reward commitment."],"summaryTask":{"instruction":"","minWords":0,"maxWords":0},"keyVocab":[]}'::jsonb),
  ('reading:x-c1-reading', 'reading', 'C1', null, null, 'The paradox of choice revisited', '{"id":"x-c1-reading","title":"The paradox of choice revisited","level":"C1","genre":"academic","intro":"An extract from a book on behavioural economics.","paragraphs":["It has become something of a truism that too much choice is bad for us. The idea, popularised in the early 2000s, rests largely on a single memorable experiment in which shoppers presented with twenty-four varieties of jam were markedly less likely to buy any than those offered only six. Choice, it seemed, could paralyse.","Yet subsequent attempts to replicate the effect have produced a rather less tidy picture. A meta-analysis of dozens of studies found that, on average, the effect of the number of options on satisfaction or purchasing was close to zero — although, crucially, the variation between studies was considerable. In some contexts, more choice demotivated people; in others, it did the opposite.","The more productive question, then, is not whether choice overload exists, but when. The evidence points to several moderating factors: whether people have clear preferences beforehand, how easily options can be compared, and whether the decision is perceived as consequential. Faced with an unfamiliar, high-stakes decision and no easy way of comparing alternatives, people do appear to struggle. Choosing a jam they already know they like poses no such difficulty.","This is not merely an academic quibble. Policies inspired by the original finding — such as drastically limiting the number of pension funds offered to employees — may be beneficial in some circumstances but counterproductive in others. The lesson, if there is one, is that striking findings deserve particular scrutiny precisely because they are so easy to remember."],"summaryTask":{"instruction":"","minWords":0,"maxWords":0},"keyVocab":[]}'::jsonb),
  ('writing:w-email-colleague', 'writing', 'B1', null, null, 'Email to a colleague', '{"id":"w-email-colleague","level":"B1","genre":"email","title":"Email to a colleague","prompt":"You are going on holiday next week. Write an email to your colleague Sam asking them to cover two of your tasks while you are away. Explain what needs to be done, give any useful information, and thank them.","minWords":80,"maxWords":120,"register":"neutral","structure":["Greeting (Hi Sam,)","Reason for writing","Task 1 + details","Task 2 + details","Thanks and offer to return the favour","Sign-off (Thanks again / Best,)"],"usefulLanguage":["Would you mind…?","Could you possibly…?","Just a quick note to ask…","In case you need anything, …","I owe you one!"]}'::jsonb),
  ('writing:w-informal-letter', 'writing', 'B1', null, null, 'Letter to a friend', '{"id":"w-informal-letter","level":"B1","genre":"informal-letter","title":"Letter to a friend","prompt":"A British friend wants to visit your region next summer. Write a letter giving recommendations: where to stay, what to see, local food to try, and practical advice.","minWords":100,"maxWords":150,"register":"informal","structure":["Friendly opening","Reaction to the news","Recommendations (2–3 paragraphs)","Practical tips","Friendly closing"],"usefulLanguage":["You really should…","If I were you, I''d…","Don''t miss…","It''s well worth…","Can''t wait to see you!"]}'::jsonb),
  ('writing:w-complaint', 'writing', 'B1+', null, null, 'Letter of complaint', '{"id":"w-complaint","level":"B1+","genre":"formal-letter","title":"Letter of complaint","prompt":"You ordered a laptop online. It arrived three weeks late and the keyboard does not work properly. Customer service has not replied to your two previous emails. Write a formal letter of complaint to the company, explaining the problem and stating what you expect them to do.","minWords":120,"maxWords":180,"register":"formal","structure":["Dear Sir or Madam,","Purpose of the letter (order number, date)","Description of the problems","Previous attempts to resolve","Request (refund / replacement / deadline)","Yours faithfully,"],"usefulLanguage":["I am writing to complain about…","To make matters worse, …","Despite having contacted…","I would therefore be grateful if you could…","I look forward to receiving your reply."]}'::jsonb),
  ('writing:w-minutes', 'writing', 'B1+', null, null, 'Meeting minutes', '{"id":"w-minutes","level":"B1+","genre":"minutes","title":"Meeting minutes","prompt":"Write the minutes (compte rendu) of a team meeting about organising a company event. Include: who attended, the points discussed (date, venue, budget), the decisions taken, and the action points with names and deadlines.","minWords":120,"maxWords":180,"register":"neutral","structure":["Title, date, attendees","Item 1: discussion + decision","Item 2: discussion + decision","Item 3: discussion + decision","Action points (who / what / by when)"],"usefulLanguage":["It was agreed that…","X raised the issue of…","The team decided to…","X will… by…","The next meeting will be held on…"]}'::jsonb),
  ('writing:w-essay-tech', 'writing', 'B2', null, null, 'Opinion essay: technology in schools', '{"id":"w-essay-tech","level":"B2","genre":"essay","title":"Opinion essay: technology in schools","prompt":"\"Smartphones should be banned in schools.\" Write an essay giving your opinion. Consider the arguments on both sides and reach a clear conclusion.","minWords":180,"maxWords":250,"register":"formal","structure":["Introduction: context + thesis","Paragraph 1: arguments for","Paragraph 2: arguments against / counter-arguments","Paragraph 3: your position with examples","Conclusion: summary + final thought"],"usefulLanguage":["It is often argued that…","On the one hand… On the other hand…","While it is true that…, …","This suggests that…","All things considered, …"]}'::jsonb),
  ('writing:w-article', 'writing', 'B2', null, null, 'Magazine article: a place that changed me', '{"id":"w-article","level":"B2","genre":"article","title":"Magazine article: a place that changed me","prompt":"An international magazine is inviting readers to write an article called ''A place that changed me''. Describe the place, explain what happened there, and why it had such an impact on you.","minWords":180,"maxWords":250,"register":"neutral","structure":["Catchy title and opening (question, anecdote)","Description of the place","What happened","Impact and reflection","Memorable ending"],"usefulLanguage":["Have you ever…?","Little did I know that…","What struck me most was…","Looking back, …","It taught me that…"]}'::jsonb),
  ('writing:w-report', 'writing', 'B2+', null, null, 'Report: improving employee well-being', '{"id":"w-report","level":"B2+","genre":"report","title":"Report: improving employee well-being","prompt":"Your manager has asked you to write a report on employee well-being in your department. Describe the current situation, present the results of an informal survey, and make recommendations.","minWords":200,"maxWords":280,"register":"formal","structure":["Title","Introduction (aim of the report)","Current situation","Survey findings (with headings)","Recommendations","Conclusion"],"usefulLanguage":["The aim of this report is to…","The majority of respondents…","A significant proportion…","It is recommended that…","Should these measures be implemented, …"]}'::jsonb),
