  ('writing:w-summary', 'writing', 'C1', null, null, 'Summary of an argument', '{"id":"w-summary","level":"C1","genre":"summary","title":"Summary of an argument","prompt":"Read the text ''Will machine translation make language learning obsolete?'' in the Reading Center, then write a summary of the author''s argument in your own words, followed by a short evaluation of whether you agree.","minWords":150,"maxWords":220,"register":"formal","structure":["Reference to the source + main thesis","Key supporting points (paraphrased)","Concession(s) made by the author","Your evaluation","Conclusion"],"usefulLanguage":["The author contends that…","According to the writer, …","While acknowledging that…, the author argues…","A compelling point is…","However, the argument could be strengthened by…"]}'::jsonb),
  ('writing:w-academic', 'writing', 'C1', null, null, 'Academic essay: the ethics of AI', '{"id":"w-academic","level":"C1","genre":"academic","title":"Academic essay: the ethics of AI","prompt":"\"The benefits of artificial intelligence outweigh its risks.\" Discuss, referring to at least two specific domains (e.g. healthcare, employment, education, justice).","minWords":250,"maxWords":350,"register":"formal","structure":["Introduction: define terms, outline structure","Domain 1: benefits vs risks","Domain 2: benefits vs risks","Synthesis: conditions under which benefits outweigh risks","Conclusion"],"usefulLanguage":["It could be argued that…","This raises the question of…","Arguably, …","Notwithstanding…","On balance, it would appear that…"]}'::jsonb),
