  ('g-tenses-1', 'grammar:tenses-review:easy', 0, 'mcq', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"easy","question":"Look! It ___ again.","options":["rains","is raining","rained"],"answer":1,"explanation":"« Look! » signale une action en cours maintenant → present continuous."}'::jsonb),
  ('g-tenses-2', 'grammar:tenses-review:easy', 1, 'gap', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"easy","text":"My brother ___ (work) in a bank. He''s been there for years.","answers":[["works"]],"explanation":"Situation stable → present simple, 3e personne : -s."}'::jsonb),
  ('g-tenses-3', 'grammar:tenses-review:easy', 2, 'mcq', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"easy","question":"I ___ my keys yesterday.","options":["lose","was losing","lost"],"answer":2,"explanation":"Action terminée, moment précis (yesterday) → past simple."}'::jsonb),
  ('g-tenses-4', 'grammar:tenses-review:easy', 3, 'gap', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"easy","text":"I ___ (not / understand) what you mean.","answers":[["don''t understand","do not understand"]],"explanation":"understand est un verbe d''état → present simple."}'::jsonb),
  ('g-tenses-5', 'grammar:tenses-review:medium', 0, 'gap', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"medium","text":"When the phone rang, I ___ (have) a shower.","answers":[["was having"]],"explanation":"Action en cours interrompue → past continuous."}'::jsonb),
  ('g-tenses-6', 'grammar:tenses-review:medium', 1, 'gap', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"medium","text":"She usually ___ (drive) to work, but this week she ___ (take) the bus.","answers":[["drives"],["is taking","''s taking"]],"explanation":"Habitude vs situation temporaire."}'::jsonb),
  ('g-tenses-7', 'grammar:tenses-review:medium', 2, 'correct', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"medium","sentence":"I am wanting a new laptop.","answers":["I want a new laptop."],"explanation":"want est un verbe d''état.","instruction":"Cette phrase contient une erreur. Réécrivez-la correctement."}'::jsonb),
  ('g-tenses-8', 'grammar:tenses-review:medium', 3, 'mcq', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"medium","question":"What ___ at 8 pm last night? I called but you didn''t answer.","options":["did you do","were you doing","do you do"],"answer":1,"explanation":"Action en cours à un moment précis du passé."}'::jsonb),
  ('g-tenses-9', 'grammar:tenses-review:hard', 0, 'gap', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"hard","text":"I ___ (think) about changing jobs. I ___ (think) it''s time.","answers":[["''m thinking","am thinking"],["think"]],"explanation":"think = réfléchir (action, -ing possible) vs think = penser/croire (état)."}'::jsonb),
  ('g-tenses-10', 'grammar:tenses-review:hard', 1, 'correct', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"hard","sentence":"While I walked home, I was seeing an accident.","answers":["While I was walking home, I saw an accident."],"explanation":"L''arrière-plan est au past continuous, l''événement ponctuel au past simple.","instruction":"Cette phrase contient une erreur. Réécrivez-la correctement."}'::jsonb),
  ('g-tenses-11', 'grammar:tenses-review:hard', 2, 'order', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"hard","words":["the","kids","were","playing","while","we","were","cooking"],"answers":["the kids were playing while we were cooking","while we were cooking the kids were playing"],"explanation":"Deux actions simultanées en cours → past continuous des deux côtés.","instruction":"Remettez les mots dans l''ordre pour former une phrase correcte."}'::jsonb),
  ('g-tenses-12', 'grammar:tenses-review:hard', 3, 'free', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"hard","task":"Décrivez en 4 à 6 phrases votre routine habituelle puis ce qui est différent cette semaine.","target":"Opposer present simple (habitudes) et present continuous (situation temporaire).","minWords":50,"model":"Normally I get up at seven and take the metro to work. This week, however, I''m working from home because the office is being renovated, so I''m getting up later and I''m cycling in the afternoon.","instruction":"Production libre"}'::jsonb),
  ('g-tenses-13', 'grammar:tenses-review:exam', 0, 'mcq', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"medium","question":"Prices ___ every year.","options":["are rising","rise","rose"],"answer":1,"explanation":"Vérité générale / tendance habituelle."}'::jsonb),
  ('g-tenses-14', 'grammar:tenses-review:exam', 1, 'gap', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"medium","text":"I ___ (read) an interesting book at the moment.","answers":[["''m reading","am reading"]]}'::jsonb),
  ('g-tenses-15', 'grammar:tenses-review:exam', 2, 'gap', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"medium","text":"We ___ (watch) TV when the lights ___ (go) out.","answers":[["were watching"],["went"]]}'::jsonb),
  ('g-tenses-16', 'grammar:tenses-review:exam', 3, 'correct', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"medium","sentence":"Do you understand? — Yes, I am understanding.","answers":["Do you understand? — Yes, I understand."],"instruction":"Cette phrase contient une erreur. Réécrivez-la correctement."}'::jsonb),
  ('g-tenses-17', 'grammar:tenses-review:exam', 4, 'mcq', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"medium","question":"This coffee ___ delicious.","options":["tastes","is tasting","tasting"],"answer":0,"explanation":"taste = avoir un goût (état)."}'::jsonb),
  ('g-tenses-18', 'grammar:tenses-review:exam', 5, 'gap', 'grammar', 'B1', 'tenses-review', 'b1-gr-tenses', '{"difficulty":"medium","text":"Where ___ you ___ (live) when you were a student?","answers":[["did"],["live"]]}'::jsonb),
  ('g-pp-1', 'grammar:present-perfect:easy', 0, 'mcq', 'grammar', 'B1', 'present-perfect', 'b1-gr-pp', '{"difficulty":"easy","question":"I ___ to Canada twice.","options":["went","have been","am"],"answer":1,"explanation":"Expérience de vie sans moment précis → present perfect."}'::jsonb),
  ('g-pp-2', 'grammar:present-perfect:easy', 1, 'gap', 'grammar', 'B1', 'present-perfect', 'b1-gr-pp', '{"difficulty":"easy","text":"She ___ (work) here since 2021.","answers":[["has worked","''s worked","has been working","''s been working"]],"explanation":"since + point de départ → present perfect."}'::jsonb),
  ('g-pp-3', 'grammar:present-perfect:easy', 2, 'mcq', 'grammar', 'B1', 'present-perfect', 'b1-gr-pp', '{"difficulty":"easy","question":"We ___ the contract last Monday.","options":["have signed","signed","sign"],"answer":1,"explanation":"last Monday = passé terminé → past simple."}'::jsonb),
  ('g-pp-4', 'grammar:present-perfect:easy', 3, 'gap', 'grammar', 'B1', 'present-perfect', 'b1-gr-pp', '{"difficulty":"easy","text":"Have you ___ (ever / eat) Indian food?","answers":[["ever eaten"]],"explanation":"ever se place avant le participe passé."}'::jsonb),
  ('g-pp-5', 'grammar:present-perfect:medium', 0, 'gap', 'grammar', 'B1', 'present-perfect', 'b1-gr-pp', '{"difficulty":"medium","text":"I ___ (lose) my phone. I can''t find it anywhere.","answers":[["''ve lost","have lost"]],"explanation":"Résultat présent (je ne le trouve pas) → present perfect."}'::jsonb),
  ('g-pp-6', 'grammar:present-perfect:medium', 1, 'gap', 'grammar', 'B1', 'present-perfect', 'b1-gr-pp', '{"difficulty":"medium","text":"He ___ (move) to Berlin three years ago and he ___ (live) there ever since.","answers":[["moved"],["has lived","''s lived","has been living","''s been living"]],"explanation":"ago → past simple ; ever since → present perfect."}'::jsonb),
